const ORCHESTRATION_ENV_LABELS = ORCH_REG?.ENV_LABELS || { dev: "Development", staging: "Staging", prod: "Production" };
const ORCHESTRATION_TRIGGER_LABELS = ORCH_REG?.TRIGGER_LABELS || { manual: "Manual run", schedule: "On a schedule", webhook: "Webhook" };
const ORCHESTRATION_APPROVAL_LABELS = ORCH_REG?.APPROVAL_LABELS || { pending: "Needs approval", approved: "Approved", rejected: "Rejected" };
const ORCHESTRATION_STUDIO_PHASES = ORCH_REG?.STUDIO_PHASES || [];
const ORCHESTRATION_MAX_PARALLEL_BRANCHES = ORCH_REG?.ORCHESTRATION_MAX_PARALLEL_BRANCHES || 5;
const ORCHESTRATION_MIN_PARALLEL_BRANCHES = ORCH_REG?.ORCHESTRATION_MIN_PARALLEL_BRANCHES || 2;

function isOrchestrationAnchorId(id) {
  return id === ORCHESTRATION_FLOW_START_ID || id === ORCHESTRATION_FLOW_END_ID;
}

function getOrchestrationAnchorPosition(which = "start") {
  const key = which === "end" || which === "stop" ? "end" : "start";
  const fallback = key === "end" ? { x: 80, y: 520 } : { x: 80, y: 80 };
  const current = orchestrationAnchorPositions?.[key];
  return {
    x: Number(current?.x ?? fallback.x),
    y: Number(current?.y ?? fallback.y),
  };
}

function setOrchestrationAnchorPosition(which, position) {
  const key = which === "end" || which === "stop" ? "end" : "start";
  orchestrationAnchorPositions = orchestrationAnchorPositions || { start: { x: 80, y: 80 }, end: { x: 80, y: 520 } };
  orchestrationAnchorPositions[key] = {
    x: Math.max(16, Number(position?.x || 16)),
    y: Math.max(16, Number(position?.y || 16)),
  };
}

function getOrchestrationBoardEntityById(id) {
  if (id === ORCHESTRATION_FLOW_START_ID) {
    return {
      id: ORCHESTRATION_FLOW_START_ID,
      type: "flow_start",
      name: "Start",
      position: getOrchestrationAnchorPosition("start"),
      config: {},
    };
  }
  if (id === ORCHESTRATION_FLOW_END_ID) {
    return {
      id: ORCHESTRATION_FLOW_END_ID,
      type: "flow_end",
      name: "Stop",
      position: getOrchestrationAnchorPosition("end"),
      config: {},
    };
  }
  return getOrchestrationNodeById(id);
}

function ensureOrchestrationAnchorLayout(nodes = []) {
  if (!orchestrationAnchorPositions?.start || !orchestrationAnchorPositions?.end) {
    orchestrationAnchorPositions = { start: { x: 80, y: 80 }, end: { x: 80, y: 520 } };
  }
}

function createOrchestrationStepNode(type) {
  const nodeType = String(type || "llm_chat");
  const visual = getOrchestrationNodeVisual(nodeType);
  const catalog = (typeof orchestrationNodeTypes !== "undefined" ? orchestrationNodeTypes : []).find(
    (item) => item.type === nodeType,
  ) || {};
  const id = `node-${Date.now().toString(36).slice(-6)}`;
  const config = getOrchestrationDefaultNodeConfig(nodeType);
  if (nodeType === "while_loop" || nodeType === "do_while") {
    config.source_node_id = id;
    config.json_path = "$.index";
    config.operator = "<";
    config.compare_value = String(config.compare_value || "3");
  }
  return {
    id,
    type: nodeType,
    name: String(catalog.label || visual.label || nodeType).trim(),
    config,
    position: null,
  };
}

function normalizeOrchestrationNodeName(value) {
  return String(value || "").trim().replace(/\s+/g, " ").slice(0, 120);
}

function getOrchestrationNodeDisplayName(node) {
  const custom = normalizeOrchestrationNodeName(node?.name);
  if (custom) return custom;
  const catalog = (orchestrationNodeTypes || []).find((item) => item.type === node?.type) || {};
  const visual = getOrchestrationNodeVisual(node?.type);
  return String(catalog.label || visual.label || node?.type || "Step").trim();
}

function orchestrationNodeFromGraphPayload(node, index = 0) {
  const type = String(node?.type || "llm_chat");
  const defaults = getOrchestrationDefaultNodeConfig(type);
  const config = {
    ...defaults,
    ...(node?.config && typeof node.config === "object" ? node.config : {}),
  };
  // Prefer top-level name; accept legacy config.step_name if present
  const legacyName = normalizeOrchestrationNodeName(config.step_name);
  if (Object.prototype.hasOwnProperty.call(config, "step_name")) delete config.step_name;
  // Fill blank required defaults without wiping intentional empty overrides for optional keys.
  Object.entries(defaults).forEach(([key, value]) => {
    if (config[key] == null || String(config[key]).trim() === "") {
      if (value !== undefined && value !== null && String(value).trim() !== "") {
        config[key] = value;
      }
    }
  });
  const name = normalizeOrchestrationNodeName(node?.name) || legacyName;
  return {
    id: String(node?.id || `node-${index + 1}`),
    type,
    name,
    config,
    position: node?.position && typeof node.position === "object" ? node.position : null,
  };
}

function createOrchestrationParallelGroup(branchCount = ORCHESTRATION_MIN_PARALLEL_BRANCHES) {
  const groupId = `pg-${Date.now().toString(36).slice(-6)}`;
  const safeCount = Math.max(
    ORCHESTRATION_MIN_PARALLEL_BRANCHES,
    Math.min(branchCount, ORCHESTRATION_MAX_PARALLEL_BRANCHES),
  );
  const branches = Array.from({ length: safeCount }, () => []);
  return {
    kind: "parallel",
    groupId,
    forkId: `fork-${groupId}`,
    joinId: `join-${groupId}`,
    branches,
  };
}

function isOrchestrationStepItem(item) {
  return item?.kind === "step" && item?.node;
}

function isOrchestrationParallelItem(item) {
  return item?.kind === "parallel";
}

function normalizeOrchestrationBranches(branches) {
  if (!Array.isArray(branches)) return [[], []];
  const normalized = branches.map((branch) => (Array.isArray(branch) ? branch.filter(Boolean) : []));
  while (normalized.length < ORCHESTRATION_MIN_PARALLEL_BRANCHES) normalized.push([]);
  return normalized;
}

function countOrchestrationWidgets(items = orchestrationBuilderItems) {
  let total = 0;
  (Array.isArray(items) ? items : []).forEach((item) => {
    if (isOrchestrationStepItem(item)) total += 1;
    else if (isOrchestrationParallelItem(item)) {
      normalizeOrchestrationBranches(item.branches).forEach((branch) => {
        total += branch.length;
      });
    }
  });
  return total;
}

function countOrchestrationParallelGroups(items = orchestrationBuilderItems) {
  return (Array.isArray(items) ? items : []).filter((item) => isOrchestrationParallelItem(item)).length;
}

function flattenOrchestrationNodes(items = orchestrationBuilderItems) {
  const nodes = [];
  (Array.isArray(items) ? items : []).forEach((item) => {
    if (isOrchestrationStepItem(item) && item.node) nodes.push(item.node);
    else if (isOrchestrationParallelItem(item)) {
      normalizeOrchestrationBranches(item.branches).forEach((branch) => {
        branch.forEach((node) => {
          if (node) nodes.push(node);
        });
      });
    }
  });
  return nodes;
}

function findOrchestrationNodeLocation(nodeId) {
  if (!nodeId) return null;
  for (let itemIndex = 0; itemIndex < orchestrationBuilderItems.length; itemIndex += 1) {
    const item = orchestrationBuilderItems[itemIndex];
    if (isOrchestrationStepItem(item) && item.node?.id === nodeId) {
      return { itemIndex, branchIndex: null, nodeIndex: 0, item, node: item.node };
    }
    if (isOrchestrationParallelItem(item)) {
      const branches = normalizeOrchestrationBranches(item.branches);
      for (let branchIndex = 0; branchIndex < branches.length; branchIndex += 1) {
        const branch = branches[branchIndex];
        const nodeIndex = branch.findIndex((node) => node?.id === nodeId);
        if (nodeIndex >= 0) {
          return { itemIndex, branchIndex, nodeIndex, item, node: branch[nodeIndex] };
        }
      }
    }
  }
  return null;
}

function getOrchestrationNodeById(nodeId) {
  return findOrchestrationNodeLocation(nodeId)?.node || null;
}

function findOrchestrationParallelItemByGroupId(groupId) {
  const normalized = String(groupId || "").trim();
  if (!normalized) return null;
  for (let itemIndex = 0; itemIndex < orchestrationBuilderItems.length; itemIndex += 1) {
    const item = orchestrationBuilderItems[itemIndex];
    if (isOrchestrationParallelItem(item) && item.groupId === normalized) {
      return { itemIndex, item };
    }
  }
  return null;
}

function canMoveOrchestrationBuilderItem(itemIndex, direction) {
  if (Number.isNaN(itemIndex) || itemIndex < 0) return false;
  const nextIndex = itemIndex + direction;
  return nextIndex >= 0 && nextIndex < orchestrationBuilderItems.length;
}

function moveOrchestrationBuilderItem(itemIndex, direction) {
  if (!canMoveOrchestrationBuilderItem(itemIndex, direction)) return;
  const swapWith = itemIndex + direction;
  [orchestrationBuilderItems[itemIndex], orchestrationBuilderItems[swapWith]] = [
    orchestrationBuilderItems[swapWith],
    orchestrationBuilderItems[itemIndex],
  ];
  assignOrchestrationNodePositions();
  renderOrchestrationStudio();
  setOrchestrationFeedback(
    direction < 0 ? "Moved block up in the flow." : "Moved block down in the flow.",
    "orchestrationBuilderFeedback",
    "success",
  );
}

function scrollOrchestrationSelectionIntoView() {
  const selectedId = orchestrationSelectedNodeId;
  if (!selectedId) return;
  const escaped =
    typeof CSS !== "undefined" && CSS.escape ? CSS.escape(selectedId) : selectedId.replace(/"/g, '\\"');
  const target = qs(`#orchestrationCanvasLane [data-node-id="${escaped}"]`);
  target?.scrollIntoView({ block: "nearest", inline: "nearest", behavior: "smooth" });
}

function scrollOrchestrationInspectorIntoView() {
  qs(".flow-studio-inspector")?.scrollIntoView({ block: "nearest", behavior: "smooth" });
}

function scrollParallelBranchIntoView(groupId, branchIndex) {
  const group = qs(`[data-parallel-group="${groupId}"]`);
  const branch = group?.querySelector(`[data-parallel-branch="${branchIndex}"]`);
  const scroller = group?.querySelector(".flow-parallel-branches");
  if (!branch || !scroller) return;
  const targetLeft = branch.offsetLeft - scroller.offsetLeft - 8;
  scroller.scrollTo({ left: Math.max(0, targetLeft), behavior: "smooth" });
  window.setTimeout(() => syncParallelBranchScrollUi(scroller.closest(".flow-parallel-branches-wrap")), 280);
}

function getParallelBranchOffset(groupId, branchCount = 0) {
  const raw = orchestrationParallelBranchOffset[groupId];
  const maxIndex = Math.max(0, branchCount - 1);
  if (raw === undefined || raw === null || Number.isNaN(raw)) return 0;
  return Math.max(0, Math.min(maxIndex, raw));
}

function jumpParallelBranch(groupId, branchIndex) {
  const group = qs(`[data-parallel-group="${groupId}"]`);
  const branchCount = Number(group?.getAttribute("data-branch-count") || 0);
  const branches = group ? [...group.querySelectorAll(".flow-parallel-branch")] : [];
  if (!branches.length) return;
  const clamped = Math.max(0, Math.min(branches.length - 1, branchIndex));
  orchestrationParallelBranchOffset[groupId] = clamped;
  orchestrationFocusedParallelBranchIndex = clamped;
  if (branchCount >= 3) {
    renderOrchestrationCanvas();
    renderOrchestrationInspector();
    return;
  }
  const scroller = group?.querySelector(".flow-parallel-branches");
  const branch = branches[clamped];
  if (branch && scroller) {
    scroller.scrollTo({ left: Math.max(0, branch.offsetLeft - 12), behavior: "smooth" });
  }
  syncParallelBranchScrollUi(group?.querySelector(".flow-parallel-branches-wrap"), clamped);
  window.setTimeout(() => syncParallelBranchScrollUi(group?.querySelector(".flow-parallel-branches-wrap"), clamped), 320);
}

function scrollParallelBranches(groupId, direction) {
  const group = qs(`[data-parallel-group="${groupId}"]`);
  const branchCount = Number(group?.getAttribute("data-branch-count") || 0);
  const branches = group ? [...group.querySelectorAll(".flow-parallel-branch")] : [];
  if (!branches.length) return;
  const nextIndex = getParallelBranchOffset(groupId, branches.length) + direction;
  jumpParallelBranch(groupId, nextIndex);
  if (branchCount >= 3) return;
  const scroller = group?.querySelector(".flow-parallel-branches");
  const wrap = scroller?.closest(".flow-parallel-branches-wrap");
  const branch = branches[Math.max(0, Math.min(branches.length - 1, nextIndex))];
  if (branch && scroller) {
    scroller.scrollTo({ left: Math.max(0, branch.offsetLeft - 12), behavior: "smooth" });
  }
  syncParallelBranchScrollUi(wrap, orchestrationParallelBranchOffset[groupId]);
  window.setTimeout(() => syncParallelBranchScrollUi(wrap, orchestrationParallelBranchOffset[groupId]), 320);
}

function syncParallelBranchScrollUi(wrap, visibleIndex) {
  if (!wrap) return;
  const scroller = wrap.querySelector(".flow-parallel-branches");
  if (!scroller) return;
  const group = wrap.closest(".flow-parallel-group");
  const groupId = group?.getAttribute("data-parallel-group") || "";
  const branches = scroller.querySelectorAll(".flow-parallel-branch");
  const branchCount = branches.length || Number(group?.getAttribute("data-branch-count") || 0);
  const showArrows = branchCount >= 3;
  let idx = visibleIndex;
  if (idx === undefined || idx === null) {
    idx = getParallelBranchOffset(groupId, branchCount);
  }
  const canLeft = idx > 0;
  const canRight = idx < branchCount - 1;
  wrap.classList.toggle("show-scroll-arrows", showArrows);
  wrap.classList.toggle("has-overflow", showArrows);
  wrap.classList.toggle("can-scroll-left", canLeft);
  wrap.classList.toggle("can-scroll-right", canRight);
  group?.querySelectorAll("[data-parallel-scroll]").forEach((btn) => {
    const dir = btn.getAttribute("data-parallel-scroll");
    if (dir === "-1") btn.toggleAttribute("disabled", !canLeft);
    if (dir === "1") btn.toggleAttribute("disabled", !canRight);
  });
  group?.querySelectorAll("[data-parallel-branch-jump]").forEach((tab) => {
    const tabIdx = Number(tab.getAttribute("data-parallel-branch-jump"));
    const isActive = tabIdx === idx;
    tab.classList.toggle("is-active", isActive);
    tab.setAttribute("aria-selected", isActive ? "true" : "false");
  });
  group?.querySelectorAll(".flow-parallel-branch").forEach((branchEl, i) => {
    const hidden = showArrows && i !== idx;
    branchEl.classList.toggle("is-branch-tab-hidden", hidden);
    branchEl.setAttribute("aria-hidden", hidden ? "true" : "false");
  });
  const label = group?.querySelector(`[data-parallel-visible-label="${groupId}"]`);
  if (label) label.textContent = String(idx + 1);
}

function syncAllParallelBranchScrollUi() {
  qsa("#orchestrationCanvasLane .flow-parallel-branches-wrap").forEach((wrap) => syncParallelBranchScrollUi(wrap));
}

function wireParallelBranchScrollListeners() {
  qsa("#orchestrationCanvasLane .flow-parallel-branches").forEach((scroller) => {
    scroller.addEventListener(
      "scroll",
      () => {
        const wrap = scroller.closest(".flow-parallel-branches-wrap");
        const groupId = wrap?.closest(".flow-parallel-group")?.getAttribute("data-parallel-group") || "";
        const branches = [...scroller.querySelectorAll(".flow-parallel-branch")];
        let idx = 0;
        branches.forEach((branch, i) => {
          if (branch.offsetLeft <= scroller.scrollLeft + 16) idx = i;
        });
        orchestrationParallelBranchOffset[groupId] = idx;
        syncParallelBranchScrollUi(wrap, idx);
      },
      { passive: true },
    );
  });
}

function bindParallelBranchScrollEvents() {
  const lane = qs("#orchestrationCanvasLane");
  if (!lane || lane.dataset.parallelScrollBound === "true") return;
  lane.dataset.parallelScrollBound = "true";

  lane.addEventListener(
    "wheel",
    (event) => {
      const scroller = event.target.closest(".flow-parallel-branches");
      if (!scroller) return;
      const useVerticalAsHorizontal = event.shiftKey && Math.abs(event.deltaY) > Math.abs(event.deltaX);
      const delta = useVerticalAsHorizontal ? event.deltaY : event.deltaX;
      if (!useVerticalAsHorizontal && Math.abs(event.deltaX) <= Math.abs(event.deltaY)) return;
      if (Math.abs(delta) < 1) return;
      event.preventDefault();
      scroller.scrollLeft += delta;
      syncParallelBranchScrollUi(scroller.closest(".flow-parallel-branches-wrap"));
    },
    { passive: false },
  );

  const viewport = qs("#orchestrationCanvasViewport");
  if (viewport && typeof ResizeObserver !== "undefined") {
    const resizeObserver = new ResizeObserver(() => syncAllParallelBranchScrollUi());
    resizeObserver.observe(viewport);
  }
}

function selectOrchestrationParallelGroup(groupId, options = {}) {
  orchestrationSelectedNodeId = `parallel:${groupId}`;
  if (Object.prototype.hasOwnProperty.call(options, "branchIndex")) {
    orchestrationFocusedParallelBranchIndex = options.branchIndex;
  } else if (!options.keepBranchFocus) {
    orchestrationFocusedParallelBranchIndex = null;
  }
  clearOrchestrationInsertState();
  renderOrchestrationStudio();
  scrollOrchestrationSelectionIntoView();
  scrollOrchestrationInspectorIntoView();
  requestAnimationFrame(() => {
    if (orchestrationFocusedParallelBranchIndex !== null && orchestrationFocusedParallelBranchIndex !== undefined) {
      scrollParallelBranchIntoView(groupId, orchestrationFocusedParallelBranchIndex);
    }
  });
}

function swapOrchestrationParallelBranches(itemIndex, branchIndexA, branchIndexB) {
  const item = orchestrationBuilderItems[itemIndex];
  if (!isOrchestrationParallelItem(item)) return;
  if (
    branchIndexA < 0 ||
    branchIndexB < 0 ||
    branchIndexA >= item.branches.length ||
    branchIndexB >= item.branches.length
  ) {
    return;
  }
  [item.branches[branchIndexA], item.branches[branchIndexB]] = [
    item.branches[branchIndexB],
    item.branches[branchIndexA],
  ];
  assignOrchestrationNodePositions();
  renderOrchestrationStudio();
  setOrchestrationFeedback("Reordered parallel branches.", "orchestrationBuilderFeedback", "success");
}

function moveOrchestrationParallelBranchOrder(itemIndex, branchIndex, direction) {
  swapOrchestrationParallelBranches(itemIndex, branchIndex, branchIndex + direction);
  orchestrationFocusedParallelBranchIndex = branchIndex + direction;
}

function listOrchestrationUpstreamNodesFromEdges(nodeId) {
  const targetId = String(nodeId || "").trim();
  if (!targetId) return [];
  const nodes = flattenOrchestrationNodes().filter((node) => node && node.id);
  const nodesById = new Map(nodes.map((node) => [node.id, node]));
  if (!nodesById.has(targetId)) return [];
  ensureOrchestrationBoardEdgesSeeded(nodes);
  const incoming = new Map();
  const addIncoming = (source, target) => {
    if (!source || !target || source === target) return;
    if (!nodesById.has(source) || !nodesById.has(target)) return;
    if (!incoming.has(target)) incoming.set(target, []);
    if (!incoming.get(target).includes(source)) incoming.get(target).push(source);
  };
  sanitizeOrchestrationBoardEdges(nodes.map((node) => node.id)).forEach((edge) => {
    addIncoming(edge.source, edge.target);
  });
  nodes.forEach((node) => {
    const config = node.config || {};
    ["true_branch", "false_branch", "body_branch", "exit_branch", "error_branch", "default_branch"].forEach((field) => {
      addIncoming(node.id, String(config[field] || "").trim());
    });
  });
  const visited = new Set();
  const ordered = [];
  const queue = [...(incoming.get(targetId) || [])];
  while (queue.length) {
    const id = queue.shift();
    if (!id || visited.has(id) || id === targetId) continue;
    visited.add(id);
    const node = nodesById.get(id);
    if (node) ordered.push(node);
    (incoming.get(id) || []).forEach((sourceId) => queue.push(sourceId));
  }
  return ordered.reverse();
}

function listOrchestrationNodesBefore(nodeId) {
  if (orchestrationCanvasLayout === "board") {
    const fromEdges = listOrchestrationUpstreamNodesFromEdges(nodeId);
    if (fromEdges.length) return fromEdges;
  }
  const located = findOrchestrationNodeLocation(nodeId);
  if (!located) return [];
  const prior = [];
  for (let itemIndex = 0; itemIndex < orchestrationBuilderItems.length; itemIndex += 1) {
    const item = orchestrationBuilderItems[itemIndex];
    if (itemIndex < located.itemIndex) {
      if (isOrchestrationStepItem(item)) prior.push(item.node);
      else if (isOrchestrationParallelItem(item)) {
        item.branches.forEach((branch) => branch.forEach((node) => prior.push(node)));
      }
      continue;
    }
    if (itemIndex === located.itemIndex && isOrchestrationParallelItem(item) && located.branchIndex !== null) {
      const branch = item.branches[located.branchIndex] || [];
      prior.push(...branch.slice(0, located.nodeIndex));
      break;
    }
    if (itemIndex === located.itemIndex && isOrchestrationStepItem(item)) break;
  }
  return prior;
}

function getOrchestrationPriorSteps(currentNodeId) {
  return listOrchestrationNodesBefore(currentNodeId).map((node, index) => {
    return {
      id: node.id,
      type: node.type,
      label: `${index + 1}. ${getOrchestrationNodeDisplayName(node)}`,
    };
  });
}

function getOrchestrationFallbackNodeTypes() {
  if (ORCH_REG?.getFallbackNodeTypes) return ORCH_REG.getFallbackNodeTypes();
  return [];
}

function getOrchestrationConfigFieldMeta(field, nodeType = "") {
  if (ORCH_REG?.getConfigFieldMeta) return ORCH_REG.getConfigFieldMeta(field, nodeType);
  return { label: field, placeholder: field, wide: false, multiline: false };
}

function orchestrationNodeMatchesBoardSearch(node) {
  const query = String(orchestrationBoardSearchQuery || "").trim().toLowerCase();
  if (!query) return true;
  const visual = getOrchestrationNodeVisual(node?.type);
  const catalog = orchestrationNodeTypes.find((item) => item.type === node?.type) || {};
  const keywords = (visual.keywords || []).join(" ");
  const hay = `${node?.id || ""} ${node?.name || ""} ${getOrchestrationNodeDisplayName(node)} ${node?.type || ""} ${catalog.label || ""} ${visual.label || ""} ${keywords} ${JSON.stringify(node?.config || {})}`.toLowerCase();
  return hay.includes(query);
}

function getOrchestrationMappingSections() {
  if (ORCH_REG?.getMappingSections) return ORCH_REG.getMappingSections();
  return {};
}

function getOrchestrationMappingFieldSet() {
  if (ORCH_REG?.getAllMappingFields) return new Set(ORCH_REG.getAllMappingFields());
  return new Set([
    "url",
    "headers_json",
    "body_template",
    "arguments_json",
    "prompt_template",
    "input_template",
    "query",
    "query_template",
    "content_template",
    "to_template",
    "subject_template",
    "scope_id",
  ]);
}

function getOrchestrationCustomInspectorFields(nodeType) {
  if (ORCH_REG?.getCustomInspectorFields) return new Set(ORCH_REG.getCustomInspectorFields(nodeType));
  return new Set();
}

function isOrchestrationProviderHttpApiType(nodeType) {
  if (ORCH_REG?.isProviderHttpApiType) return ORCH_REG.isProviderHttpApiType(nodeType);
  const key = String(nodeType || "").trim();
  if (!key.endsWith("_api") || key === "http_request") return false;
  // Offline fallback: fixed-host and allowlisted-host APIs both use auth_binding_id.
  return true;
}

function usesOrchestrationSchemaInspector(nodeType) {
  if (ORCH_REG?.usesSchemaDrivenInspector) return ORCH_REG.usesSchemaDrivenInspector(nodeType);
  return isOrchestrationProviderHttpApiType(nodeType);
}

function isOrchestrationMappingField(fieldName) {
  if (ORCH_REG?.isMappingField) return ORCH_REG.isMappingField(fieldName);
  return getOrchestrationMappingFieldSet().has(fieldName);
}

function getOrchestrationOutputParamHints(nodeType) {
  if (ORCH_REG?.getOutputParamHints) return ORCH_REG.getOutputParamHints(nodeType);
  return [];
}

function getOrchestrationOutputFieldPaths(stepType) {
  if (ORCH_REG?.getOutputFieldPaths) return ORCH_REG.getOutputFieldPaths(stepType);
  return ["status", "body", "response", "output", "message", "data", "result"];
}

function buildOrchestrationVariableReference(nodeId, fieldPath) {
  if (!fieldPath || fieldPath === "__full__") {
    return `{{steps['${nodeId}'].output}}`;
  }
  return `{{steps['${nodeId}'].output.${fieldPath}}}`;
}

function getOrchestrationRunContextVariables() {
  if (ORCH_REG?.getRunContextVariables) return ORCH_REG.getRunContextVariables();
  return [{ value: "{{input}}", label: "Run input" }];
}

function renderOrchestrationRunContextPicker(fieldName) {
  const tokens = getOrchestrationRunContextVariables();
  if (!tokens.length) return "";
  const options = tokens.map((item) => `<option value="${safeText(item.value)}">${safeText(item.label)}</option>`).join("");
  return `
    <select class="flow-run-context-insert" data-context-for="${safeText(fieldName)}" aria-label="Run context for ${safeText(fieldName)}">
      <option value="">Run context…</option>
      ${options}
    </select>`;
}

function insertTextAtOrchestrationCursor(input, text) {
  if (!input) return;
  if (input === document.activeElement && typeof input.selectionStart === "number") {
    const start = input.selectionStart;
    const end = input.selectionEnd ?? start;
    input.value = input.value.slice(0, start) + text + input.value.slice(end);
    const pos = start + text.length;
    input.setSelectionRange(pos, pos);
  } else {
    input.value = (input.value || "") + text;
  }
  input.dispatchEvent(new Event("input", { bubbles: true }));
  input.focus();
}

function insertOrchestrationVariableReference(reference, targetInput) {
  const active = document.activeElement;
  const target =
    targetInput ||
    (active?.matches?.("[data-inspector-config-field]") ? active : null) ||
    active?.closest?.("[data-inspector-config-field]");
  if (target?.matches?.("[data-inspector-config-field]")) {
    insertTextAtOrchestrationCursor(target, reference);
    return true;
  }
  void copyOrchestrationMappingSnippet(reference);
  return false;
}

function applyOrchestrationInspectorFieldValue(node, fieldName, value, { mode = "insert", targetInput = null } = {}) {
  const panel = qs("#orchestrationInspectorPanel");
  const target =
    targetInput ||
    panel?.querySelector(`[data-inspector-config-field="${fieldName}"]`) ||
    (document.activeElement?.matches?.("[data-inspector-config-field]")
      ? document.activeElement
      : null);
  if (!target) return false;
  if (mode === "replace") {
    target.value = value;
  } else {
    insertTextAtOrchestrationCursor(target, value);
  }
  if (node?.config && fieldName) {
    node.config[fieldName] = target.value;
  }
  target.dispatchEvent(new Event("input", { bubbles: true }));
  target.dispatchEvent(new Event("change", { bubbles: true }));
  refreshOrchestrationValidationCache();
  renderOrchestrationCanvas();
  return true;
}

function renderOrchestrationVariableFieldOptions(stepType, includeCustom = true, stepId = "") {
  const history = stepId ? orchestrationHistoryOutputShapes[stepId] : null;
  const livePaths = history
    ? listOrchestrationOutputFieldPaths(history)
        .map((path) => path.replace(/^\$\.?/, ""))
        .filter(Boolean)
    : [];
  const catalogPaths = getOrchestrationOutputFieldPaths(stepType);
  const paths = [];
  const seen = new Set();
  [...livePaths, ...catalogPaths].forEach((path) => {
    if (!path || seen.has(path)) return;
    seen.add(path);
    paths.push(path);
  });
  const options = paths
    .map((path) => {
      const live = livePaths.includes(path);
      return `<option value="${safeText(path)}">${safeText(path)}${live ? " · last run" : ""}</option>`;
    })
    .join("");
  const fullOutput = `<option value="__full__">Entire step output</option>`;
  return includeCustom
    ? `${fullOutput}${options}<option value="__custom__">Custom path…</option>`
    : `${fullOutput}${options}`;
}

function renderOrchestrationVariablePicker(currentNodeId, fieldName, { mode = "insert" } = {}) {
  const prior = getOrchestrationPriorSteps(currentNodeId);
  if (!prior.length) return "";
  const stepOptions = prior
    .map((step) => `<option value="${safeText(step.id)}">${safeText(step.label)}</option>`)
    .join("");
  return `
    <div class="flow-var-picker" data-var-picker-for="${safeText(fieldName)}" data-var-picker-mode="${safeText(mode)}">
      <select class="flow-var-picker-step" aria-label="Prior step for ${safeText(fieldName)}">
        <option value="">Insert from step…</option>
        ${stepOptions}
      </select>
      <select class="flow-var-picker-field" disabled aria-label="Output field for ${safeText(fieldName)}">
        <option value="">Select field…</option>
      </select>
    </div>`;
}

function resetOrchestrationVariablePicker(pickerEl) {
  const stepSelect = pickerEl?.querySelector(".flow-var-picker-step");
  const fieldSelect = pickerEl?.querySelector(".flow-var-picker-field");
  if (stepSelect) stepSelect.value = "";
  if (fieldSelect) {
    fieldSelect.innerHTML = '<option value="">Select field…</option>';
    fieldSelect.disabled = true;
  }
}

function bindOrchestrationVariablePickers(scope, node) {
  const root = scope || qs("#orchestrationInspectorPanel");
  if (!root) return;
  root.querySelectorAll(".flow-var-picker[data-var-picker-for]").forEach((pickerEl) => {
    const fieldName = pickerEl.getAttribute("data-var-picker-for");
    const stepSelect = pickerEl.querySelector(".flow-var-picker-step");
    const fieldSelect = pickerEl.querySelector(".flow-var-picker-field");
    const targetInput = root.querySelector(`[data-inspector-config-field="${fieldName}"]`);
    if (!stepSelect || !fieldSelect) return;

    stepSelect.addEventListener("change", () => {
      const stepId = stepSelect.value;
      fieldSelect.innerHTML = '<option value="">Select field…</option>';
      fieldSelect.disabled = !stepId;
      if (!stepId) return;
      const step = getOrchestrationPriorSteps(node.id).find((item) => item.id === stepId);
      fieldSelect.innerHTML = `<option value="">Select field…</option>${renderOrchestrationVariableFieldOptions(step?.type || "", true, stepId)}`;
    });

    fieldSelect.addEventListener("change", () => {
      const stepId = stepSelect.value;
      let fieldPath = fieldSelect.value;
      if (!stepId || !fieldPath) return;
      if (fieldPath === "__custom__") {
        fieldPath = window.prompt(
          "Enter output field path (e.g. data.email or choices[0].message.content):",
        );
        if (!fieldPath?.trim()) {
          fieldSelect.value = "";
          return;
        }
        fieldPath = fieldPath.trim();
      }
      const reference = buildOrchestrationVariableReference(stepId, fieldPath);
      const mode = pickerEl.getAttribute("data-var-picker-mode") || "insert";
      applyOrchestrationInspectorFieldValue(node, fieldName, reference, { mode, targetInput });
      resetOrchestrationVariablePicker(pickerEl);
    });
  });

  root.querySelectorAll(".flow-scope-id-preset").forEach((select) => {
    select.addEventListener("change", () => {
      const field = select.getAttribute("data-preset-for");
      if (!field) return;
      applyOrchestrationInspectorFieldValue(node, field, select.value, { mode: "replace" });
      select.value = "";
    });
  });

  root.querySelectorAll(".flow-run-context-insert").forEach((select) => {
    select.addEventListener("change", () => {
      const field = select.getAttribute("data-context-for");
      const token = select.value;
      if (!field || !token) return;
      const mode =
        root.querySelector(`.flow-var-picker[data-var-picker-for="${field}"]`)?.getAttribute("data-var-picker-mode") ||
        "insert";
      applyOrchestrationInspectorFieldValue(node, field, token, { mode });
      select.value = "";
    });
  });

  root.querySelectorAll(".flow-template-starter").forEach((select) => {
    select.addEventListener("change", () => {
      const field = select.getAttribute("data-starter-for");
      if (!field || !select.value) return;
      applyOrchestrationInspectorFieldValue(node, field, resolveOrchestrationTemplateStarter(select.value, node.id), {
        mode: "replace",
      });
      select.value = "";
    });
  });

  root.querySelectorAll(".flow-json-path-picker").forEach((select) => {
    select.addEventListener("change", () => {
      const field = select.getAttribute("data-json-path-for");
      if (!field || !select.value) return;
      applyOrchestrationInspectorFieldValue(node, field, select.value, { mode: "replace" });
      select.value = "";
    });
  });

  root.querySelectorAll(".flow-document-id-history").forEach((select) => {
    select.addEventListener("change", () => {
      const field = select.getAttribute("data-document-id-for");
      if (!field || !select.value) return;
      applyOrchestrationInspectorFieldValue(node, field, select.value, { mode: "replace" });
      select.value = "";
    });
  });

  root.querySelectorAll(".flow-data-map-var-insert").forEach((select) => {
    select.addEventListener("change", () => {
      const stepId = select.getAttribute("data-step-id");
      let fieldPath = select.value;
      if (!stepId || !fieldPath) return;
      if (fieldPath === "__custom__") {
        fieldPath = window.prompt(
          "Enter output field path (e.g. data.email or choices[0].message.content):",
        );
        if (!fieldPath?.trim()) {
          select.value = "";
          return;
        }
        fieldPath = fieldPath.trim();
      }
      const reference = buildOrchestrationVariableReference(stepId, fieldPath);
      const active = document.activeElement;
      const focusedField = active?.matches?.("[data-inspector-config-field]")
        ? active.getAttribute("data-inspector-config-field")
        : null;
      const inserted = focusedField
        ? applyOrchestrationInspectorFieldValue(node, focusedField, reference, {
            mode: "insert",
            targetInput: active,
          })
        : insertOrchestrationVariableReference(reference);
      if (!inserted) {
        setOrchestrationFeedback(
          "Copied to clipboard — focus an inspector field to insert at cursor.",
          "orchestrationBuilderFeedback",
          "info",
        );
      }
      select.value = "";
    });
  });
}

function renderOrchestrationMappingField(field, node, required = false) {
  const meta = getOrchestrationConfigFieldMeta(field, node?.type);
  let helperText = meta.helperText || "";
  if (field === "body_template" && (node.type === "email_send" || node.type === "sms_send")) {
    helperText = "Message body with {{steps['NODE_ID'].output.field}} placeholders from prior steps.";
  }
  const value = orchestrationConfigFieldValue(node.config || {}, field, meta);
  const wideClass = meta.wide ? " wide-field" : "";
  const label = field === "body_template" && (node.type === "email_send" || node.type === "sms_send")
    ? "Body (template)"
    : meta.label;
  const placeholder =
    field === "body_template" && (node.type === "email_send" || node.type === "sms_send")
      ? "Your alert text or {{steps['prior'].output.summary}}"
      : meta.placeholder || field;
  const helper = helperText ? `<span class="flow-mapping-field-hint">${safeText(helperText)}</span>` : "";
  const starter = renderOrchestrationTemplateStarterPicker(node, field);
  const runContext = renderOrchestrationRunContextPicker(field);
  const picker = renderOrchestrationVariablePicker(node.id, field);
  const prior = getOrchestrationPriorSteps(node.id);
  const documentIdHistory =
    field === "document_id"
      ? (() => {
          const historyOptions = prior
            .flatMap((step) => {
              const output = orchestrationHistoryOutputShapes[step.id];
              if (!output) return [];
              const paths = listOrchestrationOutputFieldPaths(output).filter((path) => /document|id/i.test(path));
              return paths.map((path) => ({ stepId: step.id, path }));
            })
            .slice(0, 12);
          if (!historyOptions.length) return "";
          const options = historyOptions
            .map(
              (item) =>
                `<option value="{{steps['${safeText(item.stepId)}'].output${item.path.replace(/^\$/, "")}}}">History ${safeText(item.path)} (${safeText(item.stepId)})</option>`,
            )
            .join("");
          return `<select class="flow-document-id-history" data-document-id-for="${safeText(field)}" aria-label="Document ID from prior run"><option value="">From last run…</option>${options}</select>`;
        })()
      : "";
  const rows = field === "body_template" || field === "headers_json" || field === "arguments_json" ? 5 : 3;
  const helperRow =
    starter || runContext || documentIdHistory
      ? `<div class="flow-field-helper-row">${starter}${runContext}${documentIdHistory}</div>`
      : "";
  if (meta.type === "select" && Array.isArray(meta.options)) {
    const options = meta.options
      .map((opt) => {
        const optVal = String(opt.value ?? "");
        const selected = optVal === value ? " selected" : "";
        return `<option value="${escapeOrchestrationFieldAttr(optVal)}"${selected}>${safeText(opt.label || optVal || "Default")}</option>`;
      })
      .join("");
    return `<label class="${wideClass.trim()} flow-mapping-field">
      <span class="flow-field-label">${safeText(label)}${required ? " *" : ""}</span>
      ${helper}
      ${helperRow}
      ${picker}
      <select data-inspector-config-field="${field}">${options}</select>
    </label>`;
  }
  if (meta.multiline) {
    return `<label class="${wideClass.trim()} flow-mapping-field">
      <span class="flow-field-label">${safeText(label)}${required ? " *" : ""}</span>
      ${helper}
      ${helperRow}
      ${picker}
      <textarea data-inspector-config-field="${field}" rows="${rows}" placeholder="${escapeOrchestrationFieldAttr(placeholder)}">${escapeOrchestrationFieldAttr(value)}</textarea>
    </label>`;
  }
  return `<label class="${wideClass.trim()} flow-mapping-field">
    <span class="flow-field-label">${safeText(label)}${required ? " *" : ""}</span>
    ${helper}
    ${helperRow}
    ${picker}
    <input data-inspector-config-field="${field}" value="${escapeOrchestrationFieldAttr(value)}" placeholder="${escapeOrchestrationFieldAttr(placeholder)}" />
  </label>`;
}

function renderOrchestrationMappingInputSections(node, fieldNames, requiredFields = []) {
  const sections = getOrchestrationMappingSections();
  const mappingFields = getOrchestrationMappingFieldSet();
  const present = fieldNames.filter((field) => mappingFields.has(field));
  if (!present.length) return "";
  const prior = getOrchestrationPriorSteps(node.id);
  const priorHint = prior.length
    ? `<p class="flow-inspector-tip flow-mapping-section-tip">Prior steps available: ${prior.map((s) => safeText(s.label)).join(", ")}. Use the dropdowns above each field to insert variables, or open <button type="button" class="inline-link-button orchestration-open-data-map">Variable map ⇄</button> for copy-ready snippets.</p>`
    : `<p class="flow-inspector-tip flow-inspector-warn">Add steps above this widget before mapping variables from their output.</p>`;
  const sectioned = new Set();
  let markup = Object.values(sections)
    .map((section) => {
      const fields = section.fields.filter((field) => present.includes(field));
      fields.forEach((field) => sectioned.add(field));
      if (!fields.length) return "";
      const fieldMarkup = fields
        .map((field) => renderOrchestrationMappingField(field, node, requiredFields.includes(field)))
        .join("");
      return `
        <fieldset class="flow-inspector-fieldset flow-mapping-section">
          <legend>${safeText(section.legend)}</legend>
          <p class="flow-mapping-section-intro">${safeText(section.intro)}</p>
          <div class="form-grid flow-inspector-form">${fieldMarkup}</div>
        </fieldset>`;
    })
    .join("");
  const orphanFields = present.filter((field) => !sectioned.has(field));
  if (orphanFields.length) {
    markup += `
      <fieldset class="flow-inspector-fieldset flow-mapping-section">
        <legend>Variable mapping</legend>
        <p class="flow-mapping-section-intro">Map prior step output into these fields using templates or the dropdown pickers.</p>
        <div class="form-grid flow-inspector-form">${orphanFields
          .map((field) => renderOrchestrationMappingField(field, node, requiredFields.includes(field)))
          .join("")}</div>
      </fieldset>`;
  }
  return markup + priorHint;
}

function renderOrchestrationOutputParamsSection(node) {
  const hints = getOrchestrationOutputParamHints(node.type);
  const example = getOrchestrationNodeOutputExample(node.type);
  const outputJson = JSON.stringify(example, null, 2);
  const nodeRef = `steps['${node.id}'].output`;
  const hintRows = hints.length
    ? hints
        .map(
          (item) =>
            `<li><code class="mono">${safeText(`${nodeRef}.${item.path}`)}</code><span>${safeText(item.description)}</span></li>`,
        )
        .join("")
    : `<li><code class="mono">${safeText(nodeRef)}</code><span>Full output object — inspect run history for live shapes</span></li>`;
  return `
    <fieldset class="flow-inspector-fieldset flow-mapping-section flow-output-params-section">
      <legend>Output parameters</legend>
      <p class="flow-mapping-section-intro">Downstream steps reference this widget's output after it runs. Use the node ID below in templates and JSON paths.</p>
      <dl class="flow-output-params-meta">
        <div><dt>Node ID</dt><dd class="mono">${safeText(node.id)}</dd></div>
        <div><dt>Template reference</dt><dd class="mono">{{${safeText(nodeRef)}}}</dd></div>
      </dl>
      <ul class="flow-output-params-list">${hintRows}</ul>
      <details class="flow-data-map-output-details">
        <summary>Example output shape (dry run / stub)</summary>
        <pre class="flow-data-map-code mono">${safeText(outputJson)}</pre>
      </details>
    </fieldset>`;
}

function getOrchestrationCategoryBadge(category) {
  if (ORCH_REG?.getCategoryBadgeLabel) return ORCH_REG.getCategoryBadgeLabel(category);
  return category || "";
}

function parseOrchestrationNodeIdFromError(message) {
  const text = String(message || "");
  const clientPrefix = text.match(/^(node-[a-z0-9]+):/i);
  if (clientPrefix) return clientPrefix[1];
  const quoted = text.match(/'([^']+)'/);
  if (quoted) return quoted[1];
  const duplicate = text.match(/duplicate node id: (\S+)/i);
  if (duplicate) return duplicate[1];
  return null;
}

function orchestrationConfigFieldValue(config, field, meta = {}) {
  const raw = config?.[field];
  if (raw === null || raw === undefined || raw === "") {
    if (meta.default !== undefined) return String(meta.default);
    return "";
  }
  return String(raw);
}

function escapeOrchestrationFieldAttr(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;");
}

function isOrchestrationCredentialBindingField(field) {
  const name = String(field || "").trim().toLowerCase();
  return (
    name === "auth_binding_id" ||
    name === "binding_id" ||
    name === "credential_binding_id" ||
    name === "token_binding_id" ||
    name === "hmac_secret_binding_id"
  );
}

function renderOrchestrationCredentialBindingSelect(field, value, { required = false, label = "", helper = "", wide = true } = {}) {
  const wideClass = wide ? " wide-field" : "";
  const requiredMark = required ? " *" : "";
  const helperHtml = helper ? `<span class="flow-mapping-field-hint">${safeText(helper)}</span>` : "";
  const current = String(value || "").trim();
  const selectedAttr = current ? "" : " selected";
  const currentOption = current
    ? `<option value="${escapeOrchestrationFieldAttr(current)}" selected>${escapeOrchestrationFieldAttr(current)} (loading…)</option>`
    : "";
  return `<label class="${wideClass.trim()}">${safeText(label || "Credential binding")}${requiredMark}${helperHtml}<select data-inspector-config-field="${escapeOrchestrationFieldAttr(field)}" data-credential-binding-select aria-label="${safeText(label || "Credential binding")}"><option value=""${selectedAttr}>Select credential binding…</option>${currentOption}</select></label>`;
}

function renderOrchestrationConfigFieldControl(field, node, required = false) {
  const meta = getOrchestrationConfigFieldMeta(field, node?.type);
  const value = orchestrationConfigFieldValue(node.config || {}, field, meta);
  const wideClass = meta.wide ? " wide-field" : "";
  const requiredMark = required ? " *" : "";
  const helper = meta.helperText
    ? `<span class="flow-mapping-field-hint">${safeText(meta.helperText)}</span>`
    : "";

  if (isOrchestrationCredentialBindingField(field)) {
    return renderOrchestrationCredentialBindingSelect(field, value, {
      required,
      label: meta.label || "Credential binding",
      helper: meta.helperText || "Choose a binding from Providers → Credential Bindings.",
      wide: true,
    });
  }

  if (field === "error_branch" || field === "true_branch" || field === "false_branch" || field === "default_branch") {
    const emptyLabel =
      field === "error_branch"
        ? "Stop / no error path…"
        : field === "true_branch"
          ? "Default successors…"
          : field === "default_branch"
            ? "No default branch…"
            : "Skip / default…";
    return `<label class="${wideClass.trim()}">${safeText(meta.label || field)}${requiredMark}${helper}<select data-inspector-config-field="${field}"><option value="">${safeText(emptyLabel)}</option>${renderOrchestrationBranchTargetOptions(node.id, value)}</select></label>`;
  }

  if (field === "source_node_id" || field === "source_a_node_id" || field === "source_b_node_id") {
    return `<label class="${wideClass.trim()}">${safeText(meta.label || field)}${requiredMark}${helper}<select data-inspector-config-field="${field}"><option value="">Select prior step…</option>${renderOrchestrationPriorStepOptions(node.id, value)}</select></label>`;
  }

  if (meta.type === "select" && Array.isArray(meta.options)) {
    const options = meta.options
      .map((opt) => {
        const optVal = String(opt.value ?? "");
        const selected = optVal === value ? " selected" : "";
        return `<option value="${escapeOrchestrationFieldAttr(optVal)}"${selected}>${safeText(opt.label || optVal || "Default")}</option>`;
      })
      .join("");
    return `<label class="${wideClass.trim()}">${safeText(meta.label)}${requiredMark}${helper}<select data-inspector-config-field="${field}">${options}</select></label>`;
  }

  if (meta.multiline) {
    return `<label class="${wideClass.trim()}">${safeText(meta.label)}${requiredMark}${helper}<textarea data-inspector-config-field="${field}" rows="3" placeholder="${escapeOrchestrationFieldAttr(meta.placeholder || field)}">${escapeOrchestrationFieldAttr(value)}</textarea></label>`;
  }

  const inputType = meta.inputType ? ` type="${escapeOrchestrationFieldAttr(meta.inputType)}"` : "";
  return `<label class="${wideClass.trim()}">${safeText(meta.label)}${requiredMark}${helper}<input data-inspector-config-field="${field}" value="${escapeOrchestrationFieldAttr(value)}" placeholder="${escapeOrchestrationFieldAttr(meta.placeholder || field)}"${inputType} /></label>`;
}

function getOrchestrationDefaultNodeConfig(type) {
  switch (String(type || "").trim()) {
    case "llm_chat":
      return { cache_mode: "inherit" };
    case "memory_read":
      return { scope_type: "session", scope_id: "", memory_tier: "short_term" };
    case "memory_write":
      return {
        scope_type: "session",
        scope_id: "",
        memory_tier: "short_term",
        content_template: "",
      };
    case "vector_query":
      return { store_id: "", query: "", top_k: "8" };
    case "vector_ingest":
      return { store_id: "", content_template: "" };
    case "rag_query":
      return { store_id: "", query_template: "", top_k: "8" };
    case "embedding_create":
      return {
        model_id: "text-embedding-3-small",
        input_template: "{{input}}",
        binding_id: "",
      };
    case "condition":
      return { operator: "==", json_path: "$.", true_branch: "", false_branch: "" };
    case "while_loop":
    case "do_while":
      return {
        operator: "<",
        json_path: "$.index",
        source_node_id: "",
        body_branch: "",
        exit_branch: "",
        max_iterations: "25",
        collect_results: "false",
        compare_value: "3",
      };
    case "foreach_map":
      return {
        items_path: "$",
        mapping_json: '{\n  "value": "{{item}}"\n}',
      };
    case "set_fields":
      return {
        fields_json: '{\n  "my_var": ""\n}',
      };
    case "static_data":
      return {
        fields_json: '{\n  "status": "open"\n}',
      };
    case "split_in_batches":
      return { items_path: "$", batch_size: "10", batch_index: "0" };
    default:
      return {};
  }
}

function runOrchestrationClientValidation() {
  syncOrchestrationBuilderConfigs();
  const byNodeId = {};
  const flowLevel = [];
  const warnings = [];
  const nodes = flattenOrchestrationNodes();
  const policy = orchestrationPolicySnapshot || {};
  const maxNodes = policy.max_nodes_per_flow || 50;
  if (nodes.length > maxNodes) {
    flowLevel.push(`Graph exceeds max steps (${maxNodes})`);
  }
  ensureOrchestrationNodeTypesCatalog();
  nodes.forEach((node) => {
    const issues = [];
    const catalog = orchestrationNodeTypes.find((item) => item.type === node.type) || {};
    (catalog.required_config_fields || []).forEach((field) => {
      const value = node.config?.[field];
      if (value == null || String(value).trim() === "") {
        issues.push(`Missing required field: ${field}`);
      }
    });
    if (node.type === "llm_chat") {
      const modelId = String(node.config?.model_id || "").trim();
      const agentKey = String(node.config?.agent_key || "").trim();
      if (!modelId && !agentKey) {
        issues.push("LLM Chat requires a model or agent config");
      }
    }
    if (node.type === "http_request") {
      const authType = String(node.config?.auth_type || "none").trim().toLowerCase();
      if (authType && authType !== "none" && !String(node.config?.auth_binding_id || "").trim()) {
        issues.push("HTTP auth requires a credential binding");
      }
      if (authType === "api_key" && !String(node.config?.auth_header_name || "").trim()) {
        issues.push("API key auth requires header name");
      }
    }
    if (node.type === "condition") {
      const jsonPath = String(node.config?.json_path || "").trim();
      if (jsonPath && !jsonPath.startsWith("$")) {
        issues.push("JSON path must start with $");
      }
      if (jsonPath && !String(node.config?.source_node_id || "").trim()) {
        issues.push("Select a prior step for JSON path conditions");
      }
    }
    if (node.type === "while_loop" || node.type === "do_while") {
      const jsonPath = String(node.config?.json_path || "").trim();
      const sourceId = String(node.config?.source_node_id || "").trim();
      if (jsonPath && !jsonPath.startsWith("$")) {
        issues.push("JSON path must start with $");
      }
      if (jsonPath && jsonPath !== "$" && jsonPath !== "$." && !sourceId) {
        issues.push("Select a prior step or This loop for the condition");
      }
      if (!String(node.config?.body_branch || "").trim()) {
        issues.push("Wire a Body path (first step inside the loop)");
      }
      const maxRaw = String(node.config?.max_iterations || "25").trim();
      const maxIter = Number(maxRaw);
      if (!Number.isFinite(maxIter) || maxIter < 1 || maxIter > 100) {
        issues.push("Max iterations must be between 1 and 100");
      }
      const pathUsable = Boolean(sourceId && jsonPath && jsonPath !== "$" && jsonPath !== "$.");
      const expression = String(node.config?.expression || "").trim();
      if (!pathUsable && !expression) {
        warnings.push(`${node.id}: no usable loop condition — will run until max iterations`);
      }
    }
    if (node.type === "human_approval") {
      const source = String(node.config?.approver_source || "static").trim().toLowerCase();
      if (source === "json_path" && !String(node.config?.approver_id_json_path || "").trim()) {
        issues.push("Approver ID JSON path is required");
      }
      if (source !== "json_path" && !String(node.config?.required_role || "").trim() && !node.config?.approval_title) {
        issues.push("Set approval title or required role");
      }
    }
    if (issues.length) byNodeId[node.id] = issues;
  });
  orchestrationBuilderItems.forEach((item) => {
    if (!isOrchestrationParallelItem(item)) return;
    item.branches.forEach((branch, branchIndex) => {
      if (branch.length) return;
      const key = item.forkId || `parallel:${item.groupId}`;
      byNodeId[key] = byNodeId[key] || [];
      byNodeId[key].push(`Branch ${branchIndex + 1} has no steps`);
    });
  });
  const errors = [...flowLevel];
  Object.entries(byNodeId).forEach(([nodeId, issues]) => {
    issues.forEach((issue) => errors.push(`${nodeId}: ${issue}`));
  });
  return { valid: errors.length === 0, errors, warnings, byNodeId, flowLevel };
}

function refreshOrchestrationValidationCache() {
  orchestrationClientValidationCache = runOrchestrationClientValidation();
}

function getOrchestrationNodeValidationIssues(nodeId) {
  const cache = orchestrationClientValidationCache || runOrchestrationClientValidation();
  const server = orchestrationValidationState.byNodeId || {};
  return [...new Set([...(cache.byNodeId[nodeId] || []), ...(server[nodeId] || [])])];
}

function applyOrchestrationServerValidation(result) {
  const byNodeId = {};
  const flowLevel = [];
  (result?.errors || []).forEach((err) => {
    const message = String(err);
    const nodeId = parseOrchestrationNodeIdFromError(message);
    if (nodeId && !message.includes("graph contains")) {
      byNodeId[nodeId] = byNodeId[nodeId] || [];
      byNodeId[nodeId].push(message);
    } else {
      flowLevel.push(message);
    }
  });
  orchestrationValidationState = {
    valid: Boolean(result?.valid),
    errors: result?.errors || [],
    warnings: result?.warnings || [],
    byNodeId,
    flowLevel,
  };
  refreshOrchestrationValidationCache();
}

function selectOrchestrationValidationNode(nodeId) {
  if (!nodeId) return;
  if (nodeId.startsWith("fork-")) {
    const parallelItem = orchestrationBuilderItems.find(
      (entry) => isOrchestrationParallelItem(entry) && entry.forkId === nodeId,
    );
    if (parallelItem) {
      orchestrationSelectedNodeId = `parallel:${parallelItem.groupId}`;
      orchestrationCollapsedParallelGroups.delete(parallelItem.groupId);
    } else {
      orchestrationSelectedNodeId = nodeId;
    }
  } else if (nodeId.startsWith("parallel:")) {
    orchestrationSelectedNodeId = nodeId;
    orchestrationCollapsedParallelGroups.delete(nodeId.slice("parallel:".length));
  } else {
    orchestrationSelectedNodeId = nodeId;
    const located = findOrchestrationNodeLocation(nodeId);
    if (located && isOrchestrationParallelItem(located.item)) {
      orchestrationCollapsedParallelGroups.delete(located.item.groupId);
    }
  }
  renderOrchestrationStudio();
}

function renderOrchestrationValidationPanel(options = {}) {
  const panel = qs("#orchestrationValidationPanel");
  if (!panel) return;
  const forceShow = Boolean(options.forceShow);
  if (forceShow) orchestrationValidationPanelDismissed = false;
  const client = orchestrationClientValidationCache || runOrchestrationClientValidation();
  const mergedValid = client.valid && orchestrationValidationState.valid;
  const mergedErrors = [...new Set([...(client.errors || []), ...(orchestrationValidationState.errors || [])])];
  const mergedWarnings = [...new Set([...(client.warnings || []), ...(orchestrationValidationState.warnings || [])])];
  const hasIssues = !mergedValid || mergedWarnings.length > 0;
  if (!hasIssues || !isOrchestrationFlowActive() || orchestrationValidationPanelDismissed) {
    panel.hidden = true;
    panel.innerHTML = "";
    return;
  }
  panel.hidden = false;
  panel.className = `flow-validation-panel ${mergedValid ? "is-warn" : "is-error"}`;
  const errorItems = mergedErrors.slice(0, 10);
  const warnItems = mergedWarnings.slice(0, 5);
  const moreCount = Math.max(0, mergedErrors.length - errorItems.length);
  panel.innerHTML = `
    <div class="flow-validation-head">
      <strong>${mergedValid ? "Review before run" : `${mergedErrors.length} issue${mergedErrors.length === 1 ? "" : "s"} to fix`}</strong>
      <button type="button" class="ghost flow-validation-dismiss" title="Dismiss" aria-label="Dismiss validation summary">×</button>
    </div>
    <ul class="flow-validation-list">
      ${errorItems
        .map((err) => {
          const nodeId = parseOrchestrationNodeIdFromError(err);
          const jump = nodeId ? ` data-validation-jump="${safeText(nodeId)}"` : "";
          const hint = nodeId ? " — click to fix" : "";
          return `<li class="flow-validation-item${nodeId ? " is-clickable" : ""}"${jump} tabindex="${nodeId ? "0" : "-1"}" role="${nodeId ? "button" : "listitem"}">${safeText(err)}${hint ? `<span class="flow-validation-jump-hint">${hint}</span>` : ""}</li>`;
        })
        .join("")}
      ${warnItems.map((w) => `<li class="flow-validation-item is-warn">${safeText(w)}</li>`).join("")}
    </ul>
    ${moreCount ? `<p class="flow-validation-more">+${moreCount} more — open Check for full list</p>` : ""}
  `;
  panel.querySelector(".flow-validation-dismiss")?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    orchestrationValidationPanelDismissed = true;
    panel.hidden = true;
    panel.innerHTML = "";
  });
  panel.querySelectorAll("[data-validation-jump]").forEach((item) => {
    item.addEventListener("click", () => {
      selectOrchestrationValidationNode(item.getAttribute("data-validation-jump"));
    });
    item.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        selectOrchestrationValidationNode(item.getAttribute("data-validation-jump"));
      }
    });
  });
}

function resolveOrchestrationJsonPathValue(payload, jsonPath) {
  if (!jsonPath || !String(jsonPath).startsWith("$")) {
    return { ok: false, error: "JSON path must start with $" };
  }
  let current = payload;
  const remainder = String(jsonPath).slice(1).replace(/^\./, "");
  if (!remainder) {
    return { ok: true, value: current };
  }
  const tokens = remainder.split(/\.(?![^\[]*\])/);
  for (const token of tokens) {
    if (!token) continue;
    let key = token;
    let index = null;
    const bracket = token.match(/^([^\[]+)\[(\d+)\]$/);
    if (bracket) {
      key = bracket[1];
      index = Number(bracket[2]);
    }
    if (key) {
      if (current == null || typeof current !== "object") {
        return { ok: true, value: undefined };
      }
      current = current[key];
    }
    if (index !== null) {
      if (!Array.isArray(current) || index < 0 || index >= current.length) {
        return { ok: true, value: undefined };
      }
      current = current[index];
    }
  }
  return { ok: true, value: current };
}

function evaluateOrchestrationConditionSample(payloadStr, config) {
  let payload;
  try {
    payload = JSON.parse(payloadStr || "{}");
  } catch {
    return { ok: false, error: "Sample payload must be valid JSON" };
  }
  const jsonPath = String(config?.json_path || "").trim();
  if (!jsonPath) return { ok: false, error: "Enter a JSON path first" };
  const resolved = resolveOrchestrationJsonPathValue(payload, jsonPath);
  if (!resolved.ok) return resolved;
  const operator = String(config?.operator || "==").trim();
  const value = resolved.value;
  if (operator === "exists") {
    return { ok: true, matched: value != null && value !== "", value };
  }
  const compare = config?.compare_value;
  let matched = false;
  if (operator === "contains") matched = String(value ?? "").includes(String(compare ?? ""));
  else if (operator === "==") matched = String(value) === String(compare);
  else if (operator === "!=") matched = String(value) !== String(compare);
  else if (operator === ">") matched = Number(value) > Number(compare);
  else if (operator === "<") matched = Number(value) < Number(compare);
  return { ok: true, matched, value };
}

function toggleOrchestrationParallelCollapse(groupId) {
  if (!groupId) return;
  if (orchestrationCollapsedParallelGroups.has(groupId)) {
    orchestrationCollapsedParallelGroups.delete(groupId);
  } else {
    orchestrationCollapsedParallelGroups.add(groupId);
  }
  renderOrchestrationCanvas();
}

function ensureOrchestrationNodeTypesCatalog() {
  if (orchestrationNodeTypes.length) return orchestrationNodeTypes;
  orchestrationNodeTypes = getOrchestrationFallbackNodeTypes();
  return orchestrationNodeTypes;
}

