function normalizeSpendBreakdownDimension(value) {
  const normalized = String(value || "all").trim().toLowerCase();
  if (
    [
      "all",
      "user",
      "group",
      "team",
      "request_tag",
      "cache_hit",
      "session_path",
      "has_feedback",
      "user_id",
      "scores",
    ].includes(normalized)
  ) {
    return normalized;
  }
  return "all";
}

function normalizeSpendRange(value) {
  const normalized = String(value || "1d").trim().toLowerCase();
  if (["realtime", "1d", "1w", "1m", "1y", "custom"].includes(normalized)) return normalized;
  return "1d";
}

function isoDateToday() {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function isoDateMinusDays(days) {
  const ts = new Date();
  ts.setDate(ts.getDate() - Math.max(0, Number(days) || 0));
  const year = ts.getFullYear();
  const month = String(ts.getMonth() + 1).padStart(2, "0");
  const day = String(ts.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function compactDateLabel(rawIso) {
  const ts = new Date(rawIso);
  if (Number.isNaN(ts.getTime())) return "--";
  const month = String(ts.getMonth() + 1).padStart(2, "0");
  const day = String(ts.getDate()).padStart(2, "0");
  return `${month}/${day}`;
}

function shortBucketLabel(rawIso, bucketCount) {
  if (bucketCount > 72) return compactDateLabel(rawIso);
  return shortHourLabel(rawIso);
}

function collapseTimeseriesPoints(points, maxBars = 96) {
  const rows = Array.isArray(points) ? points : [];
  if (rows.length <= maxBars) return rows;

  const step = Math.ceil(rows.length / maxBars);
  const collapsed = [];

  for (let idx = 0; idx < rows.length; idx += step) {
    const chunk = rows.slice(idx, idx + step);
    if (!chunk.length) continue;
    collapsed.push({
      hour_start: chunk[0].hour_start,
      spend_cents: chunk.reduce((sum, item) => sum + Number(item?.spend_cents || 0), 0),
      event_count: chunk.reduce((sum, item) => sum + Number(item?.event_count || 0), 0),
    });
  }

  return collapsed;
}

function spendBreakdownElementIds(scope = "overview") {
  if (scope === "cost") {
    return {
      dimension: "costSpendBreakdownDimension",
      range: "costSpendBreakdownRange",
      scopeFilter: "costSpendBreakdownScopeFilter",
      scopeLabel: "costSpendBreakdownScopeLabel",
      customRange: "costSpendBreakdownCustomRange",
      startDate: "costSpendBreakdownStartDate",
      endDate: "costSpendBreakdownEndDate",
      startTime: "costSpendBreakdownStartTime",
      endTime: "costSpendBreakdownEndTime",
      summary: "costSpendBreakdownSummary",
      chart: "costSpendBreakdownChart",
      insights: "costSpendBreakdownInsights",
      loadButton: "loadCostSpendBreakdown",
    };
  }
  if (scope === "telemetry") {
    return {
      dimension: "costTimeseriesDimension",
      summary: "costTimeseriesSummary",
      chart: "costTimeseriesChart",
      insights: null,
      loadButton: "loadCostTimeseries",
    };
  }
  return {
    dimension: "spendBreakdownDimension",
    range: "spendBreakdownRange",
    scopeFilter: "spendBreakdownScopeFilter",
    scopeLabel: "spendBreakdownScopeLabel",
    customRange: "spendBreakdownCustomRange",
    startDate: "spendBreakdownStartDate",
    endDate: "spendBreakdownEndDate",
    startTime: "spendBreakdownStartTime",
    endTime: "spendBreakdownEndTime",
    summary: "spendBreakdownSummary",
    chart: "spendBreakdownChart",
    insights: "spendBreakdownInsights",
    loadButton: "loadSpendBreakdown",
  };
}

function updateSpendFilterControls(scope = "overview") {
  const ids = spendBreakdownElementIds(scope);
  const dimensionSelector = qs(`#${ids.dimension}`);
  const rangeSelector = qs(`#${ids.range}`);
  const scopeInput = qs(`#${ids.scopeFilter}`);
  const scopeLabel = qs(`#${ids.scopeLabel}`);
  const customRange = qs(`#${ids.customRange}`);
  const startDate = qs(`#${ids.startDate}`);
  const endDate = qs(`#${ids.endDate}`);
  const startTime = qs(`#${ids.startTime}`);
  const endTime = qs(`#${ids.endTime}`);
  if (!dimensionSelector || !rangeSelector || !scopeInput || !scopeLabel || !customRange || !startDate || !endDate || !startTime || !endTime) return;

  const dimension = normalizeSpendBreakdownDimension(dimensionSelector.value);
  const range = normalizeSpendRange(rangeSelector.value);
  const switchedToCustom = range === "custom" && lastSpendRangeSelection !== "custom";

  const scopeMap = {
    all: { label: "Filter", placeholder: "Not used for All", disabled: true },
    user: { label: "Username", placeholder: "Filter by username", disabled: false },
    team: { label: "Team Name", placeholder: "Filter by team name", disabled: false },
    group: { label: "Group Name", placeholder: "Filter by group name", disabled: false },
    request_tag: { label: "Request Tag", placeholder: "Filter by request tag", disabled: false },
    cache_hit: { label: "Cache", placeholder: "Helicone-style cache hit/miss buckets", disabled: true },
    session_path: { label: "Session path", placeholder: "Filter by Helicone session_path substring" },
    has_feedback: {
      label: "Feedback",
      placeholder: "Filter has_feedback / no_feedback",
      disabled: false,
    },
    user_id: { label: "User id", placeholder: "Filter by Helicone user / user_id", disabled: false },
    scores: { label: "Score key", placeholder: "Filter by feedback score key", disabled: false },
  };
  const scopeSettings = scopeMap[dimension] || scopeMap.all;
  scopeLabel.textContent = scopeSettings.label;
  scopeInput.placeholder = scopeSettings.placeholder;
  scopeInput.disabled = scopeSettings.disabled;
  if (scopeSettings.disabled) scopeInput.value = "";

  customRange.hidden = range !== "custom";
  const today = isoDateToday();
  if (!endDate.value) endDate.value = today;
  if (!startDate.value) startDate.value = isoDateMinusDays(6);
  if (!startTime.value) startTime.value = "00:00";
  if (!endTime.value) endTime.value = "23:59";

  if (switchedToCustom) {
    const end = new Date();
    const start = new Date(end.getTime() - 60 * 60 * 1000);
    const formatDate = (ts) => {
      const year = ts.getFullYear();
      const month = String(ts.getMonth() + 1).padStart(2, "0");
      const day = String(ts.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    };
    const formatTime = (ts) => {
      const hour = String(ts.getHours()).padStart(2, "0");
      const minute = String(ts.getMinutes()).padStart(2, "0");
      return `${hour}:${minute}`;
    };

    startDate.value = formatDate(start);
    startTime.value = formatTime(start);
    endDate.value = formatDate(end);
    endTime.value = formatTime(end);
  }

  if (startDate.value > endDate.value) {
    startDate.value = endDate.value;
  }

  lastSpendRangeSelection = range;
}

function renderSpendBreakdownChart(payload, scope = "overview") {
  const ids = spendBreakdownElementIds(scope);
  const target = qs(`#${ids.chart}`);
  if (!target) return;
  target.textContent = "";

  const points = Array.isArray(payload?.points) ? payload.points : [];
  if (!points.length) {
    const empty = document.createElement("p");
    empty.className = "spend-breakdown-empty";
    empty.textContent = "No hourly spend data available for the selected view.";
    target.appendChild(empty);
    setSpendInsights(["No spend activity in the selected window."], scope);
    return;
  }

  const pointsToRender = collapseTimeseriesPoints(points, 96);
  const maxSpend = Math.max(...pointsToRender.map((item) => Number(item?.spend_cents || 0)), 1);

  const width = 920;
  const height = 280;
  const margin = { top: 16, right: 16, bottom: 52, left: 58 };
  const plotWidth = width - margin.left - margin.right;
  const plotHeight = height - margin.top - margin.bottom;
  const step = plotWidth / Math.max(pointsToRender.length, 1);
  const barWidth = Math.max(8, step * 0.62);

  const svgNs = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(svgNs, "svg");
  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
  svg.setAttribute("class", "spend-breakdown-svg");

  const gradient = document.createElementNS(svgNs, "linearGradient");
  gradient.setAttribute("id", scope === "cost" ? "costSpendBreakdownGradient" : scope === "telemetry" ? "costTimeseriesGradient" : "spendBreakdownGradient");
  gradient.setAttribute("x1", "0");
  gradient.setAttribute("y1", "0");
  gradient.setAttribute("x2", "0");
  gradient.setAttribute("y2", "1");
  const stopTop = document.createElementNS(svgNs, "stop");
  stopTop.setAttribute("offset", "0%");
  stopTop.setAttribute("stop-color", "var(--accent, #4f8cff)");
  stopTop.setAttribute("stop-opacity", "0.95");
  const stopBottom = document.createElementNS(svgNs, "stop");
  stopBottom.setAttribute("offset", "100%");
  stopBottom.setAttribute("stop-color", "var(--accent, #4f8cff)");
  stopBottom.setAttribute("stop-opacity", "0.35");
  gradient.append(stopTop, stopBottom);
  svg.appendChild(gradient);

  const yAxisSteps = 4;
  for (let i = 0; i <= yAxisSteps; i += 1) {
    const yValue = (maxSpend / yAxisSteps) * i;
    const yPos = height - margin.bottom - (yValue / maxSpend) * plotHeight;
    const line = document.createElementNS(svgNs, "line");
    line.setAttribute("x1", String(margin.left));
    line.setAttribute("x2", String(width - margin.right));
    line.setAttribute("y1", String(yPos));
    line.setAttribute("y2", String(yPos));
    line.setAttribute("class", "spend-breakdown-gridline");
    svg.appendChild(line);

    const label = document.createElementNS(svgNs, "text");
    label.setAttribute("x", String(margin.left - 8));
    label.setAttribute("y", String(yPos + 4));
    label.setAttribute("text-anchor", "end");
    label.setAttribute("class", "spend-breakdown-y-label");
    label.textContent = currency(Math.round(yValue));
    svg.appendChild(label);
  }

  const labelStep = Math.max(1, Math.ceil(pointsToRender.length / 8));
  pointsToRender.forEach((point, idx) => {
    const spend = Number(point?.spend_cents || 0);
    const xCenter = margin.left + step * idx + step / 2;
    const barHeight = (spend / maxSpend) * plotHeight;
    const barY = height - margin.bottom - barHeight;

    const rect = document.createElementNS(svgNs, "rect");
    rect.setAttribute("x", String(xCenter - barWidth / 2));
    rect.setAttribute("y", String(barY));
    rect.setAttribute("width", String(barWidth));
    rect.setAttribute("height", String(Math.max(1, barHeight)));
    rect.setAttribute("rx", "2");
    rect.setAttribute("class", "spend-breakdown-bar");
    rect.setAttribute("fill", scope === "cost" ? "url(#costSpendBreakdownGradient)" : scope === "telemetry" ? "url(#costTimeseriesGradient)" : "url(#spendBreakdownGradient)");
    svg.appendChild(rect);

    if (idx % labelStep === 0 || idx === pointsToRender.length - 1) {
      const xLabel = document.createElementNS(svgNs, "text");
      xLabel.setAttribute("x", String(xCenter));
      xLabel.setAttribute("y", String(height - margin.bottom + 16));
      xLabel.setAttribute("text-anchor", "middle");
      xLabel.setAttribute("class", "spend-breakdown-x-label");
      xLabel.textContent = shortBucketLabel(point?.hour_start, pointsToRender.length);
      svg.appendChild(xLabel);
    }
  });

  target.appendChild(svg);
  setSpendInsights(buildSpendInsights(payload), scope);
}

async function loadSpendBreakdown(scope = "overview") {
  const ids = spendBreakdownElementIds(scope);
  const selector = qs(`#${ids.dimension}`);
  const rangeSelector = qs(`#${ids.range}`);
  const scopeInput = qs(`#${ids.scopeFilter}`);
  const startDateInput = qs(`#${ids.startDate}`);
  const endDateInput = qs(`#${ids.endDate}`);
  const startTimeInput = qs(`#${ids.startTime}`);
  const endTimeInput = qs(`#${ids.endTime}`);
  const summary = qs(`#${ids.summary}`);
  if (!selector || !rangeSelector || !scopeInput || !summary) return;

  const dimension = normalizeSpendBreakdownDimension(selector.value);
  const range = normalizeSpendRange(rangeSelector.value);
  const hoursMap = { realtime: 1, "1d": 24, "1w": 24 * 7, "1m": 24 * 30, "1y": 24 * 365 };
  const scopeFilter = String(scopeInput.value || "").trim();

  const query = {
    dimension,
  };

  if (range === "custom") {
    const startDate = String(startDateInput?.value || "").trim();
    const endDate = String(endDateInput?.value || "").trim();
    const startTime = String(startTimeInput?.value || "").trim();
    const endTime = String(endTimeInput?.value || "").trim();
    if (!startDate || !endDate || !startTime || !endTime) {
      summary.textContent = "Choose start/end date and time for custom range.";
      renderSpendBreakdownChart({ points: [] }, scope);
      setSpendInsights(["Pick a full date range to calculate spend insights."], scope);
      return;
    }
    const startDateTime = `${startDate}T${startTime}:00`;
    const endDateTime = `${endDate}T${endTime}:59`;
    if (startDateTime > endDateTime) {
      summary.textContent = "Start date/time must be earlier than end date/time.";
      renderSpendBreakdownChart({ points: [] }, scope);
      setSpendInsights(["Fix date order to load hourly spend insights."], scope);
      return;
    }
    query.start_datetime = startDateTime;
    query.end_datetime = endDateTime;
  } else {
    query.window_hours = String(hoursMap[range] || 24);
  }

  if (dimension !== "all" && scopeFilter) {
    query.scope_filter = scopeFilter;
  }

  summary.textContent = "Loading spend vs hours...";

  try {
    const response = await api(`/cost/timeseries${buildQueryString(query)}`);
    renderSpendBreakdownChart(response, scope);
    const startDate = String(startDateInput?.value || "").trim();
    const endDate = String(endDateInput?.value || "").trim();
    const startTime = String(startTimeInput?.value || "").trim();
    const endTime = String(endTimeInput?.value || "").trim();
    const rangeText = range === "custom" ? `${startDate} ${startTime} to ${endDate} ${endTime}` : spendRangeLabel(range, startDate, endDate);
    const scopeText =
      dimension === "all"
        ? "all"
        : `${safeText(response?.dimension || dimension)}${scopeFilter ? ` (${safeText(scopeFilter)})` : ""}`;
    summary.textContent = `${rangeText} spend vs hours for ${scopeText}. Total: ${currency(response?.total_spend_cents)} across ${safeText(response?.total_event_count)} events.`;
  } catch (err) {
    renderSpendBreakdownChart({ points: [] }, scope);
    setSpendInsights(["Unable to compute spend insights until timeseries data is available."], scope);
    summary.textContent = `Error: ${safeText(err.message)}`;
  }
}

function setSpendInsights(items, scope = "overview") {
  const ids = spendBreakdownElementIds(scope);
  const target = qs(`#${ids.insights}`);
  if (!target) return;
  target.textContent = "";
  (Array.isArray(items) ? items : []).forEach((item) => {
    const li = document.createElement("li");
    li.textContent = safeText(item);
    target.appendChild(li);
  });
}

function spendRangeLabel(range, startDate, endDate) {
  if (range === "realtime") return "realtime (15m)";
  if (range === "1d") return "1 day";
  if (range === "1w") return "1 week";
  if (range === "1m") return "1 month";
  if (range === "1y") return "1 year";
  return `${startDate} to ${endDate}`;
}

function shortHourLabel(rawIso) {
  const ts = new Date(rawIso);
  if (Number.isNaN(ts.getTime())) return "--";
  const hour = ts.getHours();
  return `${String(hour).padStart(2, "0")}:00`;
}

function buildSpendInsights(response) {
  const points = Array.isArray(response?.points) ? response.points : [];
  if (!points.length) {
    return ["No spend activity in the selected window."];
  }

  const total = Number(response?.total_spend_cents || 0);
  const events = Number(response?.total_event_count || 0);
  const sortedBySpend = [...points].sort((a, b) => Number(b.spend_cents || 0) - Number(a.spend_cents || 0));
  const peak = sortedBySpend[0];
  const peakShare = total > 0 ? (Number(peak?.spend_cents || 0) / total) * 100 : 0;

  const last = points[points.length - 1] || { spend_cents: 0, hour_start: "--" };
  const prev = points[points.length - 2] || { spend_cents: 0, hour_start: "--" };
  const delta = Number(last.spend_cents || 0) - Number(prev.spend_cents || 0);
  const trend = delta > 0 ? "up" : delta < 0 ? "down" : "flat";

  const avgPerEvent = events > 0 ? total / events : 0;

  return [
    `Peak spend hour: ${shortHourLabel(peak?.hour_start)} at ${currency(Number(peak?.spend_cents || 0))} (${peakShare.toFixed(1)}% of window spend).`,
    `Recent hourly trend is ${trend} (${delta >= 0 ? "+" : ""}${currency(delta)} vs previous hour).`,
    `Average spend per event is ${currency(avgPerEvent)} across ${events} events.`,
  ];
}

async function loadCost() {
  try {
    const cost = await api("/cost/live");
    const hourEl = qs("#costHour");
    const dayEl = qs("#costDay");
    const eventsEl = qs("#costEvents");
    if (hourEl) hourEl.textContent = currency(cost?.spend_last_hour_cents);
    if (dayEl) dayEl.textContent = currency(cost?.spend_last_day_cents);
    if (eventsEl) eventsEl.textContent = String(cost?.event_count_last_day ?? "--");
    syncCostOverviewMetrics();
  } catch (err) {
    ["#costHour", "#costDay", "#costEvents", "#costOverviewHour", "#costOverviewDay", "#costOverviewEvents"].forEach((sel) => {
      const el = qs(sel);
      if (el) el.textContent = "--";
    });
  }
}

async function loadLeadershipQbrSnapshot(evt) {
  if (evt?.preventDefault) evt.preventDefault();
  const result = qs("#leadershipQbrResult");
  try {
    const data = await api("/gateway/governance/qbr-snapshot?hours=2160");
    const clocks = data?.clocks || {};
    const gates = data?.gates || {};
    const drills = data?.drills || {};
    if (qs("#qbrProdUnmanagedOk")) {
      qs("#qbrProdUnmanagedOk").textContent = clocks.prod_unmanaged_zero_ok ? "yes" : "no";
    }
    if (qs("#qbrBreakGlass")) qs("#qbrBreakGlass").textContent = safeText(gates.active_break_glass ?? "--");
    if (qs("#qbrRtFresh")) {
      qs("#qbrRtFresh").textContent = drills.rt_01_02_within_90d ? "fresh" : "due";
    }
    if (qs("#qbrTabletopFresh")) {
      qs("#qbrTabletopFresh").textContent = drills.tabletop_within_180d ? "fresh" : "due";
    }
    if (qs("#qbrLeaderClaim")) {
      qs("#qbrLeaderClaim").textContent = data?.honesty?.leader_claim_allowed ? "allowed" : "blocked";
    }
    if (qs("#qbrCpliScore")) {
      const cpli = data?.control_plane_leadership || {};
      qs("#qbrCpliScore").textContent =
        cpli.score != null ? `${cpli.score}/${cpli.max_score || 20} · ${String(cpli.band || "").replace(/_/g, " ")}` : "--";
    }
    if (qs("#qbrCpliGate")) {
      const cpli = data?.control_plane_leadership || {};
      qs("#qbrCpliGate").textContent =
        cpli.release_gate_passed == null ? "--" : cpli.release_gate_passed ? "pass" : "fail";
    }
    if (qs("#qbrCpliGateCi")) {
      const cpli = data?.control_plane_leadership || {};
      qs("#qbrCpliGateCi").textContent =
        cpli.release_gate_passed == null ? "--" : cpli.release_gate_passed ? "go" : "no_go";
    }
    if (qs("#qbrCpliPromotion")) {
      const cpli = data?.control_plane_leadership || {};
      qs("#qbrCpliPromotion").textContent =
        cpli.promotion_ready == null
          ? "--"
          : cpli.promotion_ready
            ? `ready (${cpli.gate_streak || 0}/${cpli.gate_streak_required || 2})`
            : `blocked (${cpli.gate_streak || 0}/${cpli.gate_streak_required || 2})`;
    }
    if (qs("#qbrCpliReady")) {
      const cpli = data?.control_plane_leadership || {};
      qs("#qbrCpliReady").textContent = cpli.control_ready == null ? "--" : cpli.control_ready ? "ready" : "not ready";
    }
    if (qs("#qbrCpliContract")) {
      const cpli = data?.control_plane_leadership || {};
      qs("#qbrCpliContract").textContent = cpli.contract_version || "--";
    }
    if (qs("#qbrCpliLkg")) {
      const cpli = data?.control_plane_leadership || {};
      qs("#qbrCpliLkg").textContent = cpli.last_known_good_fingerprint
        ? String(cpli.last_known_good_fingerprint).slice(0, 12)
        : "none";
    }
    if (qs("#qbrCpliReadonly")) {
      const cpli = data?.control_plane_leadership || {};
      qs("#qbrCpliReadonly").textContent =
        cpli.control_readonly == null ? "--" : cpli.control_readonly ? "frozen" : "off";
    }
    const notes = Array.isArray(data?.readiness_notes) ? data.readiness_notes.slice(0, 2).join(" · ") : "";
    if (result) {
      result.textContent = `QBR snapshot ${safeText(data?.generated_at || "")}${notes ? ` — ${safeText(notes)}` : ""}`;
    }
  } catch (err) {
    ["#qbrProdUnmanagedOk", "#qbrBreakGlass", "#qbrRtFresh", "#qbrTabletopFresh", "#qbrLeaderClaim", "#qbrCpliScore", "#qbrCpliGate", "#qbrCpliGateCi", "#qbrCpliPromotion", "#qbrCpliReady", "#qbrCpliContract", "#qbrCpliLkg", "#qbrCpliReadonly"].forEach((id) => {
      if (qs(id)) qs(id).textContent = "--";
    });
    if (result) result.textContent = `Error: ${safeText(err.message)}`;
  }
}

function renderLeadershipDrillRunsTable() {
  const table = qs("#leadershipDrillRunsTable");
  if (!table) return;
  if (!leadershipDrillRunRows.length) {
    setTableMessage(table, 7, "No drill runs recorded.");
    return;
  }
  table.textContent = "";
  leadershipDrillRunRows.forEach((row) => {
    appendTableRow(table, [
      row.run_id || "--",
      row.drill_id || "--",
      row.performed_on || "--",
      row.outcome || "--",
      row.duration_seconds ?? "--",
      row.recorded_by || "--",
      row.evidence_ref || "--",
    ]);
  });
}

async function loadLeadershipDrillRuns(evt) {
  if (evt?.preventDefault) evt.preventDefault();
  const result = qs("#leadershipDrillRunsResult");
  const table = qs("#leadershipDrillRunsTable");
  const form = qs("#leadershipDrillRunFilters");
  if (table) setTableMessage(table, 7, "Loading...");
  const raw = form ? Object.fromEntries(new FormData(form).entries()) : {};
  const query = buildQueryString({
    drill_id: raw.drill_id,
    limit: raw.limit || 50,
  });
  try {
    const data = await api(`/gateway/governance/drill-runs${query}`);
    leadershipDrillRunRows = Array.isArray(data?.items) ? data.items : [];
    renderLeadershipDrillRunsTable();
    const freshness = data?.freshness || {};
    if (result) {
      result.textContent = `Loaded ${leadershipDrillRunRows.length} drill runs. RT 90d: ${
        freshness.rt_01_02_within_90d ? "fresh" : "due"
      }; tabletop 180d: ${freshness.tabletop_within_180d ? "fresh" : "due"}.`;
    }
  } catch (err) {
    leadershipDrillRunRows = [];
    renderLeadershipDrillRunsTable();
    if (result) result.textContent = `Error: ${safeText(err.message)}`;
  }
}

async function createLeadershipDrillRun(evt) {
  if (evt?.preventDefault) evt.preventDefault();
  const form = qs("#leadershipDrillRunForm");
  const result = qs("#leadershipDrillRunsResult");
  if (!form || !result) return;
  const raw = Object.fromEntries(new FormData(form).entries());
  const performedOn = String(raw.performed_on || "").trim();
  if (!performedOn) {
    result.textContent = "Performed on date is required.";
    return;
  }
  const durationRaw = String(raw.duration_seconds || "").trim();
  const payload = {
    drill_id: String(raw.drill_id || "").trim(),
    performed_on: performedOn,
    outcome: String(raw.outcome || "pass").trim() || "pass",
    notes: String(raw.notes || "").trim(),
    evidence_ref: String(raw.evidence_ref || "").trim(),
  };
  if (durationRaw !== "") payload.duration_seconds = Number(durationRaw);
  try {
    const data = await api("/gateway/governance/drill-runs", {
      method: "POST",
      body: JSON.stringify(payload),
    });
    result.textContent = `Recorded drill run ${safeText(data.run_id)} for ${safeText(data.drill_id)}.`;
    await loadLeadershipDrillRuns();
    await loadLeadershipQbrSnapshot();
  } catch (err) {
    result.textContent = `Error: ${safeText(err.message)}`;
  }
}

async function loadGatewayAnalytics(evt) {
  if (evt?.preventDefault) evt.preventDefault();
  const form = qs("#gatewayAnalyticsFilters");
  const result = qs("#gatewayAnalyticsResult");
  const topModels = qs("#gatewayTopModelsTable");
  const topEndpoints = qs("#gatewayTopEndpointTable");
  if (!form || !result || !topModels || !topEndpoints) return;

  const raw = Object.fromEntries(new FormData(form).entries());
  const query = buildQueryString({
    environment: raw.environment,
    hours: raw.hours,
  });

  setTableMessage(topModels, 3, "Loading...");
  setTableMessage(topEndpoints, 3, "Loading...");

  try {
    const data = await api(`/gateway/analytics/summary${query}`);
    qs("#gatewayEvents").textContent = safeText(data?.total_events);
    qs("#gatewayRequests").textContent = safeText(data?.distinct_requests);
    qs("#gatewayCost").textContent = currency(Number(data?.total_estimated_cost_cents || 0));
    if (qs("#costOverviewGateway")) qs("#costOverviewGateway").textContent = currency(Number(data?.total_estimated_cost_cents || 0));
    qs("#gatewayAvgInput").textContent = Number(data?.avg_input_tokens || 0).toFixed(1);
    qs("#gatewayAvgOutput").textContent = Number(data?.avg_output_tokens || 0).toFixed(1);
    qs("#gatewayWindowHours").textContent = safeText(data?.hours);
    const onPlanePct = data?.on_plane_coverage_percent;
    if (qs("#gatewayOnPlaneCoverage")) {
      qs("#gatewayOnPlaneCoverage").textContent =
        onPlanePct == null || onPlanePct === "" ? "--" : `${Number(onPlanePct).toFixed(1)}%`;
    }
    if (qs("#gatewayOnPlaneEvents")) qs("#gatewayOnPlaneEvents").textContent = safeText(data?.on_plane_events ?? "--");
    if (qs("#gatewayOffPlaneDetected")) {
      qs("#gatewayOffPlaneDetected").textContent = safeText(data?.off_plane_detected ?? "--");
    }
    const coverageNote =
      onPlanePct == null || onPlanePct === ""
        ? "on-plane coverage n/a (no events)"
        : `on-plane ${Number(onPlanePct).toFixed(1)}%`;
    result.textContent = `Loaded gateway analytics for ${safeText(data?.environment || "all environments")} in ${safeText(data?.hours)}h window (${coverageNote}).`;

    const modelRows = Array.isArray(data?.top_models) ? data.top_models : [];
    if (!modelRows.length) {
      setTableMessage(topModels, 3, "No model analytics found.");
    } else {
      topModels.textContent = "";
      modelRows.forEach((row) => appendTableRow(topModels, [row.model_name, row.events, row.cost_cents]));
    }

    const endpointRows = Array.isArray(data?.top_endpoint_families) ? data.top_endpoint_families : [];
    if (!endpointRows.length) {
      setTableMessage(topEndpoints, 3, "No endpoint analytics found.");
    } else {
      topEndpoints.textContent = "";
      endpointRows.forEach((row) => appendTableRow(topEndpoints, [row.endpoint_family, row.events, row.cost_cents]));
    }
  } catch (err) {
    qs("#gatewayEvents").textContent = "--";
    qs("#gatewayRequests").textContent = "--";
    qs("#gatewayCost").textContent = "--";
    qs("#gatewayAvgInput").textContent = "--";
    qs("#gatewayAvgOutput").textContent = "--";
    qs("#gatewayWindowHours").textContent = "--";
    if (qs("#gatewayOnPlaneCoverage")) qs("#gatewayOnPlaneCoverage").textContent = "--";
    if (qs("#gatewayOnPlaneEvents")) qs("#gatewayOnPlaneEvents").textContent = "--";
    if (qs("#gatewayOffPlaneDetected")) qs("#gatewayOffPlaneDetected").textContent = "--";
    result.textContent = `Error: ${safeText(err.message)}`;
    setTableMessage(topModels, 3, `Error: ${safeText(err.message)}`);
    setTableMessage(topEndpoints, 3, `Error: ${safeText(err.message)}`);
  }
}

function renderCostBudgetRows() {
  const tbody = qs("#costBudgetTable");
  if (!tbody) return;
  if (!costBudgetRows.length) {
    setTableMessage(tbody, 13, "No budget policies found.");
    return;
  }
  const filter = String(costBudgetDecisionFilter || "all").toLowerCase();
  const sorted = [...costBudgetRows].sort(
    (a, b) => Number(b.utilization_percent || 0) - Number(a.utilization_percent || 0)
  );
  const visible = sorted.filter((row) => {
    if (filter === "all") return true;
    if (filter === "soft") return Boolean(row.soft_alert_active);
    return String(row.decision || "allow").toLowerCase() === filter;
  });
  if (!visible.length) {
    setTableMessage(tbody, 13, "No budget policies match this decision filter.");
    return;
  }
  tbody.textContent = "";
  visible.forEach((row) => {
    const tr = document.createElement("tr");
    const effectiveBudget = Number(row.effective_budget_cents || row.budget_amount_cents || 0);
    const spendCents = Number(row.current_spend_cents || 0);
    const hoursSpend = Number(row.hours_spend_cents || 0);
    const utilPercent = Number(row.utilization_percent || 0);
    const temporaryIncrease = Number(row.temporary_increase_cents || 0);
    const resetTimezone = String(row.reset_timezone || "UTC");
    const resetHour = Number(row.reset_hour_local ?? 0);
    const controlsSummary = [
      `reset ${resetTimezone}@${String(resetHour).padStart(2, "0")}:00`,
      temporaryIncrease > 0
        ? `temp +${temporaryIncrease}c${row.temporary_increase_active ? " active" : " expired"}`
        : "temp none",
      row.soft_alert_enabled ? "soft alert on" : "soft alert off",
      row.soft_alert_active ? "soft active" : "soft inactive",
      row.rate_limit_tpm ? `tpm ${row.rate_limit_tpm}` : "tpm --",
      row.rate_limit_rpm ? `rpm ${row.rate_limit_rpm}` : "rpm --",
      row.session_iteration_cap ? `iter ${row.session_iteration_cap}` : "iter --",
      row.session_budget_cents ? `session ${row.session_budget_cents}c` : "session --",
    ].join("; ");
    [
      row.budget_policy_id,
      `${row.scope_type}:${row.scope_id}`,
      `${row.budget_amount_cents}c`,
      row.window_type,
      `${spendCents}c`,
      `${hoursSpend}c`,
      `${utilPercent}%`,
      row.decision || "allow",
      row.recommended_action || "--",
      `${row.soft_limit_percent}% / ${row.hard_limit_percent}% (eff ${effectiveBudget}c)`,
      controlsSummary,
      row.status,
    ].forEach((value) => {
      const td = document.createElement("td");
      td.textContent = safeText(value);
      tr.appendChild(td);
    });
    fillCostUtilCell(tr.children[6], utilPercent);
    fillCostDecisionCell(tr.children[7], row.decision || "allow");

    const actions = document.createElement("td");
    actions.className = "cell-actions";

    const useBtn = document.createElement("button");
    useBtn.type = "button";
    useBtn.className = "ghost";
    useBtn.textContent = "Use";
    useBtn.addEventListener("click", () => {
      fillCostBudgetFormFromRow(row);
    });

    const explainBtn = document.createElement("button");
    explainBtn.type = "button";
    explainBtn.className = "ghost";
    explainBtn.textContent = "Explain";
    explainBtn.addEventListener("click", () => {
      const select = qs("#costBudgetSectionSelect");
      if (select) {
        select.value = "hierarchy";
        select.dispatchEvent(new Event("change"));
      }
      const form = qs("#costHierarchyForm");
      if (form?.elements?.window_mode) form.elements.window_mode.value = "budget";
      void loadCostHierarchyExplain(row.scope_type, row.scope_id);
    });

    const deleteBtn = document.createElement("button");
    deleteBtn.type = "button";
    deleteBtn.className = "ghost";
    deleteBtn.textContent = "Delete";
    deleteBtn.addEventListener("click", async () => {
      const result = qs("#costBudgetResult");
      const approved = await operatorConfirm(`Delete budget policy ${row.budget_policy_id}?`, {
        title: "Delete budget policy",
        okLabel: "Delete",
        danger: true,
      });
      if (!approved) return;
      if (result) result.textContent = `Deleting budget policy ${row.budget_policy_id}...`;
      try {
        await api(`/cost/budgets/${encodeURIComponent(row.budget_policy_id)}`, { method: "DELETE" });
        await loadCostBudgetPolicies();
        if (result) result.textContent = `Deleted budget policy ${row.budget_policy_id}.`;
      } catch (err) {
        if (result) result.textContent = `Error: ${safeText(err.message)}`;
      }
    });

    actions.append(useBtn, explainBtn, deleteBtn);
    const env = String(qs("#costBudgetListFilters")?.elements?.environment?.value || "").trim();
    appendCostBudgetRemediationActions(actions, row, {
      environment: env,
      resultSelector: "#costBudgetResult",
      onDone: () => void loadCostBudgetPolicies(),
    });
    tr.appendChild(actions);
    tbody.appendChild(tr);
  });
}

async function openCostBudgetPolicyEditor(ref = {}) {
  const budgetsTab = qs('[data-console-tab="budgets"]');
  if (budgetsTab) budgetsTab.click();
  const select = qs("#costBudgetSectionSelect");
  if (select) {
    select.value = "policies";
    select.dispatchEvent(new Event("change"));
  }
  const environment = String(ref.environment || "").trim();
  const listFilters = qs("#costBudgetListFilters");
  if (listFilters?.elements?.environment && environment) {
    listFilters.elements.environment.value = environment;
  }
  if (!costBudgetRows.length || environment) {
    await loadCostBudgetPolicies();
  }
  const policyId = String(ref.budget_policy_id || "").trim();
  const scopeType = String(ref.scope_type || "").trim();
  const scopeId = String(ref.scope_id || "").trim();
  const match =
    (policyId && costBudgetRows.find((item) => item.budget_policy_id === policyId)) ||
    costBudgetRows.find((item) => item.scope_type === scopeType && item.scope_id === scopeId) ||
    null;
  if (match) {
    fillCostBudgetFormFromRow(match);
    return;
  }
  const form = qs("#costBudgetForm");
  const result = qs("#costBudgetResult");
  if (form) {
    if (policyId) form.elements.budget_policy_id.value = policyId;
    if (scopeType) form.elements.scope_type.value = scopeType;
    if (scopeId) form.elements.scope_id.value = scopeId;
  }
  if (result) {
    result.textContent = policyId
      ? `Opened policy ${policyId}. Load budgets if fields are incomplete.`
      : `Opened scope ${scopeType}:${scopeId}. Load budgets to edit.`;
  }
}

function openCostPolicyEvaluate(ref = {}) {
  const budgetsTab = qs('[data-console-tab="budgets"]');
  if (budgetsTab) budgetsTab.click();
  const select = qs("#costBudgetSectionSelect");
  if (select) {
    select.value = "evaluate";
    select.dispatchEvent(new Event("change"));
  }
  const form = qs("#costPolicyEvalForm");
  if (!form) return;
  if (ref.scope_type) form.elements.scope_type.value = ref.scope_type;
  if (ref.scope_id) form.elements.scope_id.value = ref.scope_id;
  if (form.elements.environment) {
    form.elements.environment.value = String(ref.environment || "").trim();
  }
  if (ref.window_type && form.elements.window_type) {
    form.elements.window_type.value = ref.window_type;
  }
  void evaluateCostPolicy();
}

async function applyCostBudgetTemporaryIncrease(policyId, options = {}) {
  const id = String(policyId || "").trim();
  if (!id) return null;
  const centsRaw = options.increase_cents ?? window.prompt("Temporary increase (cents)", "500");
  if (centsRaw == null) return null;
  const increaseCents = Number(centsRaw);
  if (!Number.isFinite(increaseCents) || increaseCents < 1) {
    throw new Error("Increase must be a positive cents amount.");
  }
  const minutesRaw = options.duration_minutes ?? window.prompt("Duration (minutes)", "60");
  if (minutesRaw == null) return null;
  const durationMinutes = Number(minutesRaw);
  if (!Number.isFinite(durationMinutes) || durationMinutes < 1) {
    throw new Error("Duration must be at least 1 minute.");
  }
  const reason = options.reason || "operator-temporary-increase";
  return api(`/cost/budgets/${encodeURIComponent(id)}/increase-temporary`, {
    method: "POST",
    body: JSON.stringify({
      increase_cents: increaseCents,
      duration_minutes: durationMinutes,
      reason,
    }),
  });
}

async function clearCostBudgetTemporaryIncrease(policyId) {
  const id = String(policyId || "").trim();
  if (!id) return null;
  return api(`/cost/budgets/${encodeURIComponent(id)}/increase-temporary/clear`, { method: "POST", body: "{}" });
}

async function acknowledgeCostBudgetSoftAlert(policyId, reason = "operator-acknowledged") {
  const id = String(policyId || "").trim();
  if (!id) return null;
  return api(`/cost/budgets/${encodeURIComponent(id)}/soft-alert/acknowledge`, {
    method: "POST",
    body: JSON.stringify({ reason }),
  });
}

function appendCostBudgetRemediationActions(actionCell, row, context = {}) {
  if (!actionCell || !row?.budget_policy_id) return;
  const environment = String(context.environment || "").trim();
  const tempBtn = document.createElement("button");
  tempBtn.type = "button";
  tempBtn.className = "ghost";
  tempBtn.textContent = "Temp +";
  tempBtn.title = "Apply temporary budget increase";
  tempBtn.addEventListener("click", async () => {
    const result = qs(context.resultSelector || "#costBudgetResult");
    try {
      await applyCostBudgetTemporaryIncrease(row.budget_policy_id);
      if (result) result.textContent = `Applied temporary increase to ${row.budget_policy_id}.`;
      await loadCostBudgetPolicies();
      if (typeof context.onDone === "function") context.onDone();
    } catch (err) {
      if (result) result.textContent = `Error: ${safeText(err.message)}`;
    }
  });
  const clearTempBtn = document.createElement("button");
  clearTempBtn.type = "button";
  clearTempBtn.className = "ghost";
  clearTempBtn.textContent = "Clear temp";
  clearTempBtn.addEventListener("click", async () => {
    const result = qs(context.resultSelector || "#costBudgetResult");
    try {
      await clearCostBudgetTemporaryIncrease(row.budget_policy_id);
      if (result) result.textContent = `Cleared temporary increase on ${row.budget_policy_id}.`;
      await loadCostBudgetPolicies();
      if (typeof context.onDone === "function") context.onDone();
    } catch (err) {
      if (result) result.textContent = `Error: ${safeText(err.message)}`;
    }
  });
  const ackBtn = document.createElement("button");
  ackBtn.type = "button";
  ackBtn.className = "ghost";
  ackBtn.textContent = "Ack soft";
  ackBtn.title = "Acknowledge soft alert for this budget window";
  ackBtn.addEventListener("click", async () => {
    const result = qs(context.resultSelector || "#costBudgetResult");
    try {
      await acknowledgeCostBudgetSoftAlert(row.budget_policy_id);
      if (result) result.textContent = `Acknowledged soft alert for ${row.budget_policy_id}.`;
      if (typeof context.onDone === "function") context.onDone();
      else {
        await loadCostAnomalies();
        await loadCostBudgetPolicies();
      }
    } catch (err) {
      if (result) result.textContent = `Error: ${safeText(err.message)}`;
    }
  });
  const evalBtn = document.createElement("button");
  evalBtn.type = "button";
  evalBtn.className = "ghost";
  evalBtn.textContent = "Evaluate";
  evalBtn.addEventListener("click", () => {
    openCostPolicyEvaluate({
      scope_type: row.scope_type,
      scope_id: row.scope_id,
      window_type: row.window_type,
      environment,
    });
  });
  actionCell.append(tempBtn, clearTempBtn, ackBtn, evalBtn);
}

